  /* ============================================================
     CÁLCULO EXACTO DE PUNTUACIÓN DE BLACKJACK (HOOK UNIFICADO)
     ============================================================ */
  function calculateHandScore(hand, isMonkStand = false, isEnemyHand = false) {
    if (!Array.isArray(hand) || hand.length === 0) return 0;
    const isEnemy = isEnemyHand || (typeof gameState !== "undefined" && gameState.enemy && hand === gameState.enemy.enemyHand);
    const gauntlet = (!isEnemy && typeof gameState !== "undefined" && gameState.player && gameState.player.accessory === "lead_gauntlet");
    let limit = BUST_LIMIT;
    let aceVal = 11;
    if (typeof arenaMatch !== "undefined" && arenaMatch && arenaMatch.currentMutator) {
      if (arenaMatch.currentMutator.id === "bust_22") limit = 22;
      if (arenaMatch.currentMutator.id === "overcharged_aces") aceVal = 12;
    }
    let score = 0;
    let aces = 0;

    for (let i = 0; i < hand.length; i++) {
      const card = hand[i];
      if (!card) continue;
      const sId = card.specialId || card.id;

      if (card.isAce) {
        aces++;
        score += aceVal;
      } else if (sId === "dark_ten") {
        if (isEnemy) {
          score -= 3;
        } else {
          score += 10;
        }
      } else if (sId === "double_jack") {
        score += 10;
      } else if (sId === "versatile_queen") {
        let neighborVal = 10;
        if (i > 0 && hand[i - 1]) {
          neighborVal = hand[i - 1].value || 10;
        } else if (i < hand.length - 1 && hand[i + 1]) {
          neighborVal = hand[i + 1].value || 10;
        }
        score += neighborVal;
      } else if (sId === "shifting_king") {
        score += 10;
      } else if (sId === "cursed_seven") {
        score += 7;
      } else if (sId === "joker_party" || (card.dynamicValues && Array.isArray(card.dynamicValues))) {
        // Se calcula después del bucle principal
        score += 0;
      } else {
        score += (gauntlet && card.value < 3) ? 3 : (card.value || 0);
      }
    }

    while (score > limit && aces > 0) {
      score -= (aceVal - 1);
      aces--;
    }

    // J Doble: si vale 10 pero valiendo 11 llega a 21 exacto
    const hasDoubleJack = hand.some(c => (c.specialId || c.id) === "double_jack");
    if (hasDoubleJack && score === limit - 1) {
      score = limit;
    }

    // 7 Astral del Tahúr (Arena): muta a 11 si no causa bust (suma +4 a los 7 ya calculados)
    const hasLuckySeven = hand.some(c => (c.specialId || c.id) === "lucky_seven_astral");
    if (hasLuckySeven && score + 4 <= limit && (score + 4 === limit || score <= limit - 4)) {
      score += 4;
    }

    // Calcular valores dinámicos
    const dynCards = hand.filter(c => (c.specialId || c.id) === "joker_party" || (c.dynamicValues && Array.isArray(c.dynamicValues)));
    dynCards.forEach(c => {
      if ((c.specialId || c.id) === "joker_party") {
        if (score + 3 <= limit) { score += 3; c.currentAdaptedValue = 3; }
        else if (score - 3 > 0) { score -= 3; c.currentAdaptedValue = -3; }
      } else if (c.dynamicValues && Array.isArray(c.dynamicValues)) {
        let bestVal = c.dynamicValues[0];
        let bestScore = -1;
        for (const val of c.dynamicValues) {
          if (score + val <= limit && score + val > bestScore) {
            bestScore = score + val;
            bestVal = val;
          }
        }
        if (bestScore === -1 && aces > 0) {
          while (aces > 0 && score > 0) {
            score -= (aceVal - 1);
            aces--;
            for (const val of c.dynamicValues) {
              if (score + val <= limit && score + val > bestScore) {
                bestScore = score + val;
                bestVal = val;
              }
            }
            if (bestScore !== -1) break;
          }
        }
        if (bestScore === -1) {
          // Si todos causan BUST, usa el valor mínimo para mitigar
          bestVal = Math.min(...c.dynamicValues);
        }
        c.currentAdaptedValue = bestVal;
        score += bestVal;
      }
    });

    while (score > limit && aces > 0) {
      score -= (aceVal - 1);
      aces--;
    }

    // K Cambiante: baja a 7 o 2 si evita BUST
    const hasShiftingKing = hand.some(c => (c.specialId || c.id) === "shifting_king");
    if (hasShiftingKing && score > limit) {
      if (score - 3 <= limit) {
        score -= 3;
      } else if (score - 8 <= limit) {
        score -= 8;
      }
    }

    // 7 Maldito: si causa BUST, muta a -2
    const hasCursedSeven = hand.some(c => (c.specialId || c.id) === "cursed_seven");
    if (hasCursedSeven && score > limit) {
      score -= 9;
    }

    // 8 Espejo: clona el valor del naipe más alto
    const hasMirrorEight = hand.some(c => (c.specialId || c.id) === "wild_eight_mirror");
    if (hasMirrorEight) {
      const otherValues = hand.filter(c => (c.specialId || c.id) !== "wild_eight_mirror").map(c => c.value || 0);
      if (otherValues.length > 0) {
        const maxOther = Math.max(...otherValues);
        if (maxOther > 8 && score - 8 + maxOther <= limit) {
          score = score - 8 + maxOther;
        }
      }
    }

    // 5 Arcano: suma +2 si la puntuación es impar
    const hasArcaneFive = hand.some(c => (c.specialId || c.id) === "arcane_five_surge");
    if (hasArcaneFive && (score % 2 !== 0) && score + 2 <= limit) {
      score += 2;
    }

    // 2 Ancla: si causa BUST, muta a 0 salvando la mano
    const hasAnchorTwo = hand.some(c => (c.specialId || c.id) === "balance_two_anchor");
    if (hasAnchorTwo && score > limit) {
      score -= 2;
    }

    // As Par: con 2 o más Ases en mano otorga +1
    const totalAces = hand.filter(c => c && (c.isAce || c.rank === "A")).length;
    const hasTwinAce = hand.some(c => (c.specialId || c.id) === "twin_ace");
    if (hasTwinAce && totalAces >= 2 && score + 1 <= limit) {
      score += 1;
    }

    // Autoajuste inteligente de Sello Maleable / Camaleónico (±1)
    const malleableCards = hand.filter(c => c && c.enchantment && (c.enchantment.id === "malleable" || c.enchantment.type === "malleable"));
    if (malleableCards.length > 0) {
      for (let i = 0; i < malleableCards.length; i++) {
        if (score > limit && (score - 1) <= limit) {
          score -= 1;
        }
      }
      if (score === limit - 1) {
        score = limit;
      }
    }

    if (isMonkStand && (score === 18 || score === 19)) {
      score += 1;
    }

    return score;
  }

  /* ============================================================
     GESTIÓN DE ESTADOS DINÁMICOS DEL SPRITE DEL JUGADOR
     ============================================================ */
  let playerSpriteTimer = null;

  function showLockedHeroNotice(heroName) {
    addLog(`🔒 ${heroName} está bloqueado en esta prueba. Elige al Caballero.`, "warning");
    const container = document.getElementById("game-container");
    if (!container) return;
    let toast = document.getElementById("hero-lock-toast");
    if (!toast) {
      toast = document.createElement("div");
      toast.id = "hero-lock-toast";
      toast.style.cssText = "position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);background:rgba(11,12,16,0.95);border:2px solid #e63946;color:#ff758f;padding:10px 14px;border-radius:6px;font-size: 9px;z-index:999;text-align:center;box-shadow:0 0 16px rgba(230,57,70,0.6);pointer-events:none;animation:totalGlow 0.3s ease-out;";
      container.appendChild(toast);
    }
    toast.innerText = `🔒 ${heroName} bloqueado en esta prueba.\n¡Elige al Caballero!`;
    toast.style.display = "block";
    setTimeout(() => { if (toast) toast.style.display = "none"; }, 1600);
  }

  function setPlayerSpriteState(state, options = {}) {
    const p = gameState.player;
    if (!p) return;
    const hero = HERO_DATA[p.class] || HERO_DATA.knight;
    const sp = document.getElementById("player-sprite");
    const spIcon = document.getElementById("player-sprite-icon");
    if (!sp || !spIcon) return;

    if (playerSpriteTimer) {
      clearTimeout(playerSpriteTimer);
      playerSpriteTimer = null;
    }

    let imgSrc = hero.img;
    let animClass = "";

    switch (state) {
      case "windup":
        imgSrc = hero.imgAttack || hero.img;
        animClass = "sprite-windup-player";
        break;
      case "strike":
      case "attack":
        imgSrc = hero.imgAttack || hero.img;
        animClass = "sprite-strike-player";
        break;
      case "recover":
        imgSrc = hero.img;
        animClass = "sprite-recover-player";
        break;
      case "block":
      case "blocked":
        imgSrc = hero.img;
        animClass = "sprite-block-player";
        break;
      case "parry":
        imgSrc = hero.imgAttack || hero.img;
        animClass = "sprite-parry-player";
        break;
      case "dodge":
        imgSrc = hero.img;
        break;
      case "hit_weak":
        imgSrc = hero.img;
        animClass = "sprite-hit-weak-player";
        break;
      case "hit_normal":
      case "hurt":
        imgSrc = hero.imgHurt || hero.img;
        animClass = "sprite-hit-normal-player";
        break;
      case "hit_crit":
        imgSrc = hero.imgHurt || hero.img;
        animClass = "sprite-hit-crit-player";
        break;
      case "blackjack":
      case "victory_pose":
        imgSrc = hero.imgAttack || hero.img;
        animClass = "sprite-victory-player";
        break;
      case "bust":
        imgSrc = hero.imgHurt || hero.img;
        animClass = "sprite-bust-player";
        break;
      case "dead":
        imgSrc = hero.imgDead || hero.img;
        animClass = "sprite-dead-player";
        break;
      case "idle":
      default:
        imgSrc = hero.img;
        animClass = "sprite-idle-player";
        break;
    }

    if (imgSrc) {
      spIcon.innerHTML = `<img src="${imgSrc}" class="sprite-img" alt="${hero.name}" onerror="this.outerHTML='${hero.sprite}'">`;
    } else {
      spIcon.innerText = hero.sprite;
    }

    sp.className = `sprite ${hero.styleClass || ""}`;
    if (animClass) sp.classList.add(animClass);

    const tempStates = ["windup", "strike", "attack", "recover", "block", "blocked", "parry", "dodge", "hit_weak", "hit_normal", "hurt", "hit_crit", "blackjack", "victory_pose", "bust"];
    if (tempStates.includes(state) && p.hp > 0) {
      const duration = (options && options.duration) ? options.duration : (state === "hit_crit" ? 750 : state === "strike" || state === "attack" ? 600 : 500);
      playerSpriteTimer = setTimeout(() => {
        if (p.hp > 0) {
          setPlayerSpriteState("idle");
        }
      }, duration);
    }
  }

  let enemySpriteTimer = null;
  function setEnemySpriteState(state, options = {}) {
    const e = gameState.enemy;
    const sp = document.getElementById("enemy-sprite");
    if (!sp) return;

    if (enemySpriteTimer) {
      clearTimeout(enemySpriteTimer);
      enemySpriteTimer = null;
    }

    let animClass = "";
    switch (state) {
      case "windup":
        animClass = "sprite-windup-enemy";
        break;
      case "strike":
      case "attack":
        animClass = "sprite-strike-enemy";
        break;
      case "recover":
        animClass = "sprite-recover-enemy";
        break;
      case "block":
      case "blocked":
        animClass = "sprite-block-enemy";
        break;
      case "hit_weak":
        animClass = "sprite-hit-weak-enemy";
        break;
      case "hit_normal":
      case "hurt":
        animClass = "sprite-hit-normal-enemy";
        break;
      case "hit_crit":
        animClass = "sprite-hit-crit-enemy";
        break;
      case "dead":
        animClass = "sprite-dead-enemy";
        break;
      case "idle":
      default:
        animClass = "sprite-idle-enemy";
        break;
    }

    const allEnemyAnim = [
      "sprite-idle-enemy", "sprite-windup-enemy", "sprite-strike-enemy", "enemy-attack", "sprite-recover-enemy",
      "sprite-block-enemy", "sprite-hit-weak-enemy", "sprite-hit-normal-enemy",
      "sprite-hit-crit-enemy", "sprite-dead-enemy", "flash-damage"
    ];
    sp.classList.remove(...allEnemyAnim);
    if (animClass) sp.classList.add(animClass);

    const tempEnemyStates = ["windup", "strike", "attack", "recover", "block", "blocked", "hit_weak", "hit_normal", "hurt", "hit_crit"];
    if (tempEnemyStates.includes(state) && (!e || e.hp > 0)) {
      const duration = (options && options.duration) ? options.duration : (state === "hit_crit" ? 750 : state === "strike" || state === "attack" ? 600 : 500);
      enemySpriteTimer = setTimeout(() => {
        if (!e || e.hp > 0) {
          setEnemySpriteState("idle");
        }
      }, duration);
    }
  }

  /* ============================================================
     META-PROGRESIÓN: PERFIL PERMANENTE Y MAESTRÍA DE LOS JACKS
     ============================================================ */
  const HERO_META_KEY = "blackjack_tower_heroes_meta_v1";

  function getHeroMeta() {
    const makeDefaults = () => ({
      knight: { totalExp: 0, masteryLevel: 1, level: 1, exp: 0, baseMaxHp: null, basePwr: null, baseDef: null, runs: 0, wins: 0, legacyPoints: 0, legacyHp: 0, legacyPwr: 0, legacyDef: 0, prestigeTrophies: 0 },
      rogue: { totalExp: 0, masteryLevel: 1, level: 1, exp: 0, baseMaxHp: null, basePwr: null, baseDef: null, runs: 0, wins: 0, legacyPoints: 0, legacyHp: 0, legacyPwr: 0, legacyDef: 0, prestigeTrophies: 0 },
      monk: { totalExp: 0, masteryLevel: 1, level: 1, exp: 0, baseMaxHp: null, basePwr: null, baseDef: null, runs: 0, wins: 0, legacyPoints: 0, legacyHp: 0, legacyPwr: 0, legacyDef: 0, prestigeTrophies: 0 },
      necromancer: { totalExp: 0, masteryLevel: 1, level: 1, exp: 0, baseMaxHp: null, basePwr: null, baseDef: null, runs: 0, wins: 0, legacyPoints: 0, legacyHp: 0, legacyPwr: 0, legacyDef: 0, prestigeTrophies: 0 }
    });
    const defaultMeta = makeDefaults();
    let meta = defaultMeta;
    let fromStorage = false;
    try {
      const parsed = _loadSecure(HERO_META_KEY, null);
      if (parsed && typeof parsed === "object") {
        const base = makeDefaults();
        meta = {};
        ["knight", "rogue", "monk", "necromancer"].forEach(hk => {
          const stored = (parsed[hk] && typeof parsed[hk] === "object") ? parsed[hk] : null;
          meta[hk] = Object.assign({}, base[hk], stored || {});
          if (stored && typeof stored.level !== "number") {
            // Guardado anterior al Nivel Permanente Real: se deriva de masteryLevel/totalExp
            meta[hk].level = null;
            meta[hk].exp = null;
          }
        });
        fromStorage = true;
      }
    } catch (e) {
      console.warn("Error cargando meta-progresión:", e);
    }
    meta = _validateMetaRanges(meta);
    if (_migrateHeroMeta(meta) && fromStorage) {
      try { _saveSecure(HERO_META_KEY, meta); } catch (_) {}
    }
    return meta;
  }

  function saveHeroMeta(meta) {
    try {
      _saveSecure(HERO_META_KEY, meta);
    } catch (e) {
      console.warn("Error guardando meta-progresión:", e);
    }
  }

  /* Fase 3: Altar del Legado — Asignación y reembolso de estadísticas permanentes */
  function upgradeHeroLegacy(heroKey, stat) {
    if (!heroKey) return;
    const meta = getHeroMeta();
    if (!meta[heroKey]) return;
    const h = meta[heroKey];
    if ((h.legacyPoints || 0) <= 0) {
      if (typeof addLog === "function") addLog("Sin Puntos de Legado. Completa la Torre (derrota a BLACK en el Piso 13) para ganarlos.", "warning");
      return;
    }

    if (stat === "hp") {
      if ((h.legacyHp || 0) >= 10) return;
      h.legacyHp = (h.legacyHp || 0) + 1;
      h.legacyPoints--;
    } else if (stat === "pwr") {
      if ((h.legacyPwr || 0) >= 5) return;
      h.legacyPwr = (h.legacyPwr || 0) + 1;
      h.legacyPoints--;
    } else if (stat === "def") {
      if ((h.legacyDef || 0) >= 5) return;
      h.legacyDef = (h.legacyDef || 0) + 1;
      h.legacyPoints--;
    }

    saveHeroMeta(meta);
    try { playCoinSound(); } catch (_) {}
    if (typeof triggerHaptic === "function") triggerHaptic("selection");
    if (typeof renderHeroBook === "function") renderHeroBook();
  }
  window.upgradeHeroLegacy = upgradeHeroLegacy;

  function refundHeroLegacy(heroKey) {
    if (!heroKey) return;
    const meta = getHeroMeta();
    if (!meta[heroKey]) return;
    const h = meta[heroKey];
    const spent = (h.legacyHp || 0) + (h.legacyPwr || 0) + (h.legacyDef || 0);
    if (spent <= 0) return;

    h.legacyPoints = (h.legacyPoints || 0) + spent;
    h.legacyHp = 0;
    h.legacyPwr = 0;
    h.legacyDef = 0;

    saveHeroMeta(meta);
    try { playEnchantChimeSound(); } catch (_) {}
    if (typeof triggerHaptic === "function") triggerHaptic("impactLight");
    if (typeof renderHeroBook === "function") renderHeroBook();
  }
  window.refundHeroLegacy = refundHeroLegacy;

  function calculateMasteryLevel(exp) {
    if (exp < 80) return 1;
    if (exp < 200) return 2;
    if (exp < 400) return 3;
    if (exp < 700) return 4;
    if (exp < 1100) return 5;
    if (exp < 1600) return 6;
    if (exp < 2300) return 7;
    if (exp < 3200) return 8;
    if (exp < 4500) return 9;
    return Math.floor(10 + (exp - 4500) / 1500);
  }

  /* Curva de experiencia por nivel de combate: Entre más nivel, más experiencia se necesita */
  function getExpRequiredForLevel(level) {
    if (level <= 1) return 60;
    if (level === 2) return 140;
    if (level === 3) return 260;
    if (level === 4) return 440;
    if (level === 5) return 700;
    if (level === 6) return 1050;
    if (level === 7) return 1550;
    if (level === 8) return 2200;
    // Suavizado polinómico/exponencial moderado a partir del nivel 8 para progresión estilo Diablo II
    return Math.floor(60 * Math.pow(1.28, level - 1) + (level - 1) * 80);
  }
  window.getExpRequiredForLevel = getExpRequiredForLevel;

  /* ============================================================
     SISTEMA DE ATRIBUTOS RPG COMPUESTOS (STR, DEX, VIT, INT)
     +5 Puntos de atributo asignables por nivel y escalado compuesto
     ============================================================ */
  function initHeroAttributes(player, heroClass) {
    const baseClass = heroClass || (player && player.class) || "knight";
    const archetypes = {
      knight:      { str: 14, dex: 10, vit: 14, int: 8,  freePoints: 0 },
      rogue:       { str: 10, dex: 16, vit: 10, int: 10, freePoints: 0 },
      monk:        { str: 12, dex: 12, vit: 12, int: 10, freePoints: 0 },
      necromancer: { str: 8,  dex: 10, vit: 10, int: 18, freePoints: 0 }
    };
    const base = archetypes[baseClass] || archetypes.knight;
    return { ...base };
  }
  window.initHeroAttributes = initHeroAttributes;

  function assignHeroAttribute(attr, points = 1) {
    const p = (window.gameState && window.gameState.player);
    if (!p) return false;
    if (!p.attributes) p.attributes = initHeroAttributes(p, p.class);
    points = Math.min(points, p.attributes.freePoints || 0);
    if (points <= 0) return false;
    if (p.attributes[attr] === undefined) p.attributes[attr] = 10;
    p.attributes[attr] += points;
    p.attributes.freePoints -= points;

    // Escalado compuesto inmediato según el atributo potenciado
    if (attr === "vit") {
      const hpGain = points * 12;
      p.maxHp += hpGain;
      p.hp = Math.min(p.maxHp, p.hp + hpGain);
      if (typeof spawnFloatingText === "function") spawnFloatingText("player-sprite", `+${hpGain} HP MÁX`, "heal");
    } else if (attr === "str") {
      p.pwr += Math.floor(points * 0.5);
      if (typeof spawnFloatingText === "function") spawnFloatingText("player-sprite", `+${Math.floor(points * 0.5)} PWR`, "crit");
    } else if (attr === "dex") {
      p.def += Math.floor(points * 0.3);
      if (typeof spawnFloatingText === "function") spawnFloatingText("player-sprite", `+${Math.floor(points * 0.3)} DEF`, "shield");
    } else if (attr === "int") {
      if (typeof spawnFloatingText === "function") spawnFloatingText("player-sprite", `+${points * 8}% ARCANO`, "magic");
    }

    if (typeof updateHud === "function") updateHud();
    if (typeof playTone === "function") playTone(587.3, 0.08, "triangle", 0.3);
    return true;
  }
  window.assignHeroAttribute = assignHeroAttribute;

  function getHeroAttributes() {
    return (window.gameState && window.gameState.player && window.gameState.player.attributes) || null;
  }
  window.getHeroAttributes = getHeroAttributes;

  /* ============================================================
     MOTOR DE COMBATE D&D + BLACKJACK (PvP Y COMBATE TÁCTICO)
     - Tirada contra CA: <15 Glance, 15-18 Hit, 19-20 Pierce, 21 Nat 20, BJ Vorpal, Bust Pifia
     - Escuelas de Pintas: ♠️ Físico, ♦️ Escudo/CA, ♥️ Curación, ♣️ Overdrive
     ============================================================ */
  function resolveDnDBlackjackRound(pScore, rScore, playerHand = [], rivalHand = [], options = {}) {
    const maxLim = options.maxLim || 21;
    const pwrAttacker = options.pwr !== undefined ? options.pwr : 12;
    const defDefender = options.def !== undefined ? options.def : 6;
    const isPlayer = options.isPlayer !== false;
    const hand = isPlayer ? playerHand : rivalHand;
    const oppHand = isPlayer ? rivalHand : playerHand;

    const suitCounts = { "♠": 0, "♦": 0, "♥": 0, "♣": 0 };
    (hand || []).forEach(c => {
      if (!c) return;
      const s = c.suit || (c.rank && c.rank.includes("♠") ? "♠" : (c.rank && c.rank.includes("♦") ? "♦" : (c.rank && c.rank.includes("♥") ? "♥" : "♣")));
      if (suitCounts[s] !== undefined) suitCounts[s]++;
      else if (s === "♠" || s === "spades") suitCounts["♠"]++;
      else if (s === "♦" || s === "diamonds") suitCounts["♦"]++;
      else if (s === "♥" || s === "hearts") suitCounts["♥"]++;
      else if (s === "♣" || s === "clubs") suitCounts["♣"]++;
    });

    const spadeBonus = suitCounts["♠"] * 2;
    const diamondShield = suitCounts["♦"] * 3;
    const heartHeal = suitCounts["♥"] * 3;
    const clubOverdrive = suitCounts["♣"] * 8;

    const isBust = pScore > maxLim;
    const isOppBust = rScore > maxLim;
    const isNaturalBJ = (pScore === maxLim && (hand || []).length === 2);
    const isOppNaturalBJ = (rScore === maxLim && (oppHand || []).length === 2);

    let tier = "hit";
    let mult = 1.0;
    let defIgnorePct = 0;
    let statusEffect = null;
    let isCrit = false;

    if (isBust) {
      tier = "bust";
      mult = 0;
      statusEffect = "exposed";
    } else if (isNaturalBJ && !isOppNaturalBJ) {
      tier = "natural_bj";
      mult = 2.5;
      defIgnorePct = 1.0;
      isCrit = true;
      statusEffect = "stun";
    } else if (pScore === maxLim) {
      tier = "crit21";
      mult = 2.0;
      defIgnorePct = 1.0;
      isCrit = true;
    } else if (pScore >= 19) {
      tier = "pierce";
      mult = 1.35;
      defIgnorePct = 0.50;
    } else if (pScore >= 15) {
      tier = "hit";
      mult = 1.0;
      defIgnorePct = 0;
    } else {
      tier = "glance";
      mult = 0.50;
      defIgnorePct = 0;
    }

    let diceDamage = 0;
    (hand || []).forEach(c => {
      if (!c) return;
      const v = typeof c.value === "number" ? c.value : parseInt(c.rank, 10) || 10;
      if (c.isAce || v === 1 || v === 11) diceDamage += 10;
      else if (v >= 10) diceDamage += 6;
      else if (v >= 6) diceDamage += 4;
      else diceDamage += 2;
    });

    const effectiveDef = Math.round(defDefender * (1 - defIgnorePct));
    let rawDamage = Math.max(8, pwrAttacker + (pScore - (isOppBust ? 0 : rScore)) - effectiveDef) + spadeBonus;
    let finalDamage = Math.round(rawDamage * mult);

    return {
      tier,
      mult,
      defIgnorePct,
      spadeBonus,
      diamondShield,
      heartHeal,
      clubOverdrive,
      diceDamage,
      finalDamage,
      isCrit,
      statusEffect,
      isNaturalBJ,
      suitCounts
    };
  }
  window.resolveDnDBlackjackRound = resolveDnDBlackjackRound;

  function simulateArenaDamage(winnerScore, loserScore, winnerPwr, loserDef, isSuddenDeath, options = {}) {
    const mult = isSuddenDeath ? 2 : 1;
    if (options.useDnD) {
      const res = resolveDnDBlackjackRound(winnerScore, loserScore, options.hand || [], options.oppHand || [], {
        pwr: winnerPwr,
        def: loserDef
      });
      return res.finalDamage * mult;
    }
    const dmg = Math.max(8, winnerPwr + (winnerScore - loserScore) - loserDef) * mult;
    return dmg;
  }
  window.simulateArenaDamage = simulateArenaDamage;

  function checkSavingThrow(reason = "bust") {
    const p = (window.gameState && window.gameState.player);
    if (!p) return false;
    const dex = (p.attributes && p.attributes.dex) || 10;
    const int = (p.attributes && p.attributes.int) || 10;
    const chance = Math.min(65, Math.max(10, 20 + Math.floor((dex - 10) * 2) + Math.floor((int - 10) * 1.5)));
    const roll = Math.random() * 100;
    if (roll < chance) {
      if (typeof spawnFloatingText === "function") {
        spawnFloatingText("player-sprite", `🎲 ¡SALVACIÓN D&D! (${Math.round(chance)}%)`, "heal");
      }
      if (typeof addLog === "function") {
        addLog(`🎲 ¡Tirada de Salvación Exitosa (${Math.round(chance)}%)! Tu Destreza (${dex}) y Arcano (${int}) mitigan el impacto.`, "critical");
      }
      return true;
    }
    return false;
  }
  window.checkSavingThrow = checkSavingThrow;

  function calculateSafeHitChance(hand = [], deck = []) {
    if (!deck || deck.length === 0) return 100;
    const curScore = calculateHandScore(hand);
    if (curScore >= 21) return 0;
    const safeCards = deck.filter(c => {
      const testHand = [...hand, c];
      return calculateHandScore(testHand) <= 21;
    });
    return Math.round((safeCards.length / deck.length) * 100);
  }
  window.calculateSafeHitChance = calculateSafeHitChance;

  function calculateCritChance(hand = [], deck = []) {
    if (!deck || deck.length === 0) return 0;
    const curScore = calculateHandScore(hand);
    if (curScore > 21) return 0;
    if (curScore >= 19 && curScore <= 21) return 100;
    const critCards = deck.filter(c => {
      const testHand = [...hand, c];
      const s = calculateHandScore(testHand);
      return s >= 19 && s <= 21;
    });
    return Math.round((critCards.length / deck.length) * 100);
  }
  window.calculateCritChance = calculateCritChance;

  function calculateExactTacticalDamage(player, enemy, playerHand = [], isDouble = false) {
    if (!player) return { dmg: 0, isCrit: false, critMult: 1.0, baseAtk: 0, flatBonus: 0, rawAtk: 0, buffMultiplier: 1.0, totalAttack: 0 };
    const score = calculateHandScore(playerHand || []);
    if (score > 21) {
      return { dmg: 0, isCrit: false, critMult: 1.0, isBust: true, baseAtk: player.pwr || 14, flatBonus: 0, rawAtk: 0, buffMultiplier: 1.0, totalAttack: 0, score };
    }

    // 1. Ataque Base del Personaje
    const baseAtk = player.pwr || 14;

    // 2. Bonos Planos de Cartas/Sellos/Reliquias/Afinidades
    let flatBonus = 0;

    // Atributos RPG: Modificador de Fuerza (STR)
    const strMod = (player.attributes && player.attributes.str > 10) ? Math.floor((player.attributes.str - 10) / 2) : 0;
    flatBonus += strMod;

    // Bonos planos de cartas/sellos en mano
    flatBonus += (player.cardBonusDamage || 0);

    // Afinidad Elemental de Picas (♠)
    let spadeBonus = 0;
    const hasSpadeAffinity = !!(player && player.affinitySpades);
    if (hasSpadeAffinity) {
      const spadeRank = (player._spadesRank || 1);
      (playerHand || []).forEach(c => {
        if (c && (c.suit === "♠" || c.suit === "spades")) spadeBonus += (spadeRank + 2);
      });
      if (player._spadesEclipseBonus) spadeBonus += player._spadesEclipseBonus;
    }
    flatBonus += spadeBonus;

    // Reliquias y accesorios
    if (typeof hasArtifact === "function") {
      if (hasArtifact("warriors_ring")) flatBonus += 3;
      if (hasArtifact("fury_bracer") && player.furyBracerStreak) flatBonus += player.furyBracerStreak;
    }
    if (player.accessory === "mercury_band") flatBonus += 2;
    if (player.gem === "topaz") flatBonus += 2;
    if (player._synergyBonusPwr) flatBonus += player._synergyBonusPwr;

    const rawAtk = baseAtk + flatBonus;

    // 3. Porcentaje de Buffs - Porcentaje de Nerfs
    let buffPct = 0;
    const gs = window.gameState;
    if (gs && gs.playerStreak >= 3) {
      buffPct += 1.0; // Racha On Fire x2.0 (+100%)
    } else if (gs && gs.playerStreak === 2) {
      buffPct += 0.5; // Racha On Fire x1.5 (+50%)
    }
    if (player._spadesVorpalBonus && (score === 20 || score === 21)) {
      buffPct += player._spadesVorpalBonus; // +15%
    }
    if (typeof hasStarterBlessing === "function" && hasStarterBlessing("berserker_rage") && (score === 20 || score === 21)) {
      buffPct += 0.30; // +30%
    }
    const buffMultiplier = Math.max(0.1, 1 + buffPct);

    // 4. Multiplicador Crítico (SOLO si supera la tirada contra player.critChance)
    let isCrit = false;
    let critMult = 1.0;
    const critChance = (player && typeof player.critChance === "number") ? player.critChance : 0;
    if (critChance > 0 && Math.random() * 100 < critChance) {
      isCrit = true;
      const isNatBJ = (score === 21 && (playerHand || []).length === 2);
      critMult = isNatBJ ? 2.5 : 2.0;
    }

    // 5. Multiplicador de Doblar
    const doubleMult = (isDouble || player.turnDoubleDamage) ? 2.0 : 1.0;

    // Daño Total antes de armadura
    const totalAttack = Math.round(rawAtk * buffMultiplier * doubleMult * (isCrit ? critMult : 1.0));

    // Mitigación por Defensa Rival
    const effectiveEnemyDef = enemy ? Math.max(0, (enemy.def || 0) - (player.sharpArmorPierce || 0)) : 0;
    const dmg = Math.max(0, totalAttack - effectiveEnemyDef);

    return {
      dmg,
      totalAttack,
      isCrit,
      critMult,
      score,
      baseAtk,
      flatBonus,
      rawAtk,
      buffMultiplier,
      doubleMult,
      effectiveEnemyDef
    };
  }
  window.calculateExactTacticalDamage = calculateExactTacticalDamage;

  /* ============================================================
     VALIDACIÓN DEFENSIVA DE ESTADO DE COMBATE (v1.7.6)
     Previene crashes por condiciones de carrera o referencias nulas
     en el WebView de Android/Capacitor al entrar al primer combate.
     ============================================================ */
  function ensureBattleStateInitialized() {
    try {
      if (!window.gameState || typeof window.gameState !== "object") {
        window.gameState = {};
      }
      const gs = window.gameState;
      if (!gs.player || typeof gs.player !== "object") {
        gs.player = {
          name: "Jack",
          class: "knight",
          hp: 100,
          maxHp: 100,
          pwr: 5,
          def: 2,
          level: 1,
          exp: 0,
          potions: 2,
          rerollsAvailable: 0,
          handNumber: 0,
          betAmount: 0,
          playerHand: [],
          deck: [],
          artifacts: [],
          cardUpgrades: [],
          cardEnchantments: {}
        };
      }
      const p = gs.player;
      const heroKey = p.classKey || p.class || "knight";
      const heroCfg = (typeof HERO_DATA !== "undefined" && HERO_DATA[heroKey]) ? HERO_DATA[heroKey] : (HERO_DATA.knight || {});
      p.hp = (typeof p.hp === "number" && !isNaN(p.hp)) ? p.hp : (p.maxHp || 100);
      p.maxHp = Math.max(1, (typeof p.maxHp === "number" && !isNaN(p.maxHp)) ? p.maxHp : 100);
      p.pwr = (typeof p.pwr === "number" && !isNaN(p.pwr)) ? p.pwr : 5;
      p.def = (typeof p.def === "number" && !isNaN(p.def)) ? p.def : 2;
      p.critChance = Number(p.critChance) || (heroCfg.critChance || 0);
      p.dodgeChance = Number(p.dodgeChance) || (heroCfg.dodgeChance || 0);
      p.thorns = (typeof p.thorns === "number" && !isNaN(p.thorns)) ? p.thorns : (heroCfg.thorns || 0);
      p.handNumber = Number(p.handNumber) || 0;
      p.betAmount = Number(p.betAmount) || 0;
      if (!Array.isArray(p.playerHand)) p.playerHand = [];
      if (!Array.isArray(p.deck)) p.deck = [];
      if (!Array.isArray(p.artifacts)) p.artifacts = [];
      if (!Array.isArray(p.cardUpgrades)) p.cardUpgrades = [];
      if (!p.cardEnchantments || typeof p.cardEnchantments !== "object") p.cardEnchantments = {};
      if (!p.attributes || typeof p.attributes !== "object") {
        p.attributes = { str: 10, dex: 10, int: 10, con: 10, fth: 10, cha: 10 };
      }

      if (!gs.status || typeof gs.status !== "object") {
        gs.status = {};
      }
      gs.status.playerShield = Number(gs.status.playerShield) || 0;
      gs.status.enemyShield = Number(gs.status.enemyShield) || 0;
      gs.status.playerPoison = Number(gs.status.playerPoison) || 0;
      gs.status.enemyPoison = Number(gs.status.enemyPoison) || 0;
      gs.status.playerBurn = Number(gs.status.playerBurn) || 0;
      gs.status.enemyBurn = Number(gs.status.enemyBurn) || 0;

      if (!gs.enemy || typeof gs.enemy !== "object" || !gs.enemy.name) {
        if (Array.isArray(gs.floorEnemies) && gs.floorEnemies.length > 0 && gs.floorEnemies[gs.currentEnemyIndex || 0]) {
          gs.enemy = Object.assign({}, gs.floorEnemies[gs.currentEnemyIndex || 0]);
        } else {
          gs.enemy = {
            name: "Espectro de la Torre",
            sprite: "💀",
            hp: 60,
            maxHp: 60,
            pwr: 3,
            def: 1,
            enemyHand: []
          };
        }
      }
      const e = gs.enemy;
      e.maxHp = Math.max(1, (typeof e.maxHp === "number" && !isNaN(e.maxHp)) ? e.maxHp : 60);
      e.hp = (typeof e.hp === "number" && !isNaN(e.hp)) ? e.hp : e.maxHp;
      e.pwr = (typeof e.pwr === "number" && !isNaN(e.pwr)) ? e.pwr : 3;
      e.def = (typeof e.def === "number" && !isNaN(e.def)) ? e.def : 0;
      if (!Array.isArray(e.enemyHand)) e.enemyHand = [];

      // Validar mazo de robo
      if (typeof drawPile !== "undefined" && (!Array.isArray(drawPile) || drawPile.length < 4)) {
        if (typeof rebuildDrawPile === "function") rebuildDrawPile();
      }

      // Validar persistencia de mazos por héroe para evitar lecturas de undefined
      try {
        const storedDecks = localStorage.getItem("torre21_hero_decks");
        if (!storedDecks) {
          localStorage.setItem("torre21_hero_decks", "{}");
        }
      } catch (_) {}

      return true;
    } catch (err) {
      console.warn("ensureBattleStateInitialized catch fallback:", err);
      return false;
    }
  }
  window.ensureBattleStateInitialized = ensureBattleStateInitialized;

  /* ============================================================
     ÁLBUMES DE BENDICIONES Y RELIQUIAS COLECCIONABLES (v1.7.6)
     ============================================================ */
  function getUnlockedBlessings() {
    try {
      const raw = localStorage.getItem("torre21_unlocked_blessings") || localStorage.getItem("bj_unlocked_blessings") || "[]";
      const list = JSON.parse(raw);
      return Array.isArray(list) ? list : [];
    } catch (_) {
      return [];
    }
  }
  window.getUnlockedBlessings = getUnlockedBlessings;

  function unlockBlessingInCodex(id) {
    if (!id || typeof id !== "string") return;
    try {
      const list = getUnlockedBlessings();
      if (!list.includes(id)) {
        list.push(id);
        localStorage.setItem("torre21_unlocked_blessings", JSON.stringify(list));
        localStorage.setItem("bj_unlocked_blessings", JSON.stringify(list));
      }
    } catch (_) {}
  }
  window.unlockBlessingInCodex = unlockBlessingInCodex;

  function getUnlockedRelics() {
    try {
      const raw = localStorage.getItem("torre21_unlocked_relics") || localStorage.getItem("bj_unlocked_relics") || "[]";
      const list = JSON.parse(raw);
      return Array.isArray(list) ? list : [];
    } catch (_) {
      return [];
    }
  }
  window.getUnlockedRelics = getUnlockedRelics;

  function unlockRelicInCodex(id) {
    if (!id || typeof id !== "string") return;
    try {
      const list = getUnlockedRelics();
      if (!list.includes(id)) {
        list.push(id);
        localStorage.setItem("torre21_unlocked_relics", JSON.stringify(list));
        localStorage.setItem("bj_unlocked_relics", JSON.stringify(list));
      }
    } catch (_) {}
  }
  window.unlockRelicInCodex = unlockRelicInCodex;

  function calculateTacticalAttackRange(player, enemy, playerHand = [], isDouble = false) {
    if (!player) return { minDmg: 0, maxDmg: 0, text: "⚔️ ATAQUE: 0", score: 0 };
    const score = calculateHandScore(playerHand || []);
    if (score > 21) {
      return { minDmg: 0, maxDmg: 0, text: "⚔️ ATAQUE: 0 (BUST)", isBust: true, score };
    }

    // 1. Ataque Base del Personaje
    const baseAtk = player.pwr || 14;

    // 2. Bonos Planos
    let flatBonus = 0;
    const strMod = (player.attributes && player.attributes.str > 10) ? Math.floor((player.attributes.str - 10) / 2) : 0;
    flatBonus += strMod;
    flatBonus += (player.cardBonusDamage || 0);

    let spadeBonus = 0;
    const hasSpadeAffinity = !!(player && player.affinitySpades);
    if (hasSpadeAffinity) {
      const spadeRank = (player._spadesRank || 1);
      (playerHand || []).forEach(c => {
        if (c && (c.suit === "♠" || c.suit === "spades")) spadeBonus += (spadeRank + 2);
      });
      if (player._spadesEclipseBonus) spadeBonus += player._spadesEclipseBonus;
    }
    flatBonus += spadeBonus;

    if (typeof hasArtifact === "function") {
      if (hasArtifact("warriors_ring")) flatBonus += 3;
      if (hasArtifact("fury_bracer") && player.furyBracerStreak) flatBonus += player.furyBracerStreak;
    }
    if (player.accessory === "mercury_band") flatBonus += 2;
    if (player.gem === "topaz") flatBonus += 2;
    if (player._synergyBonusPwr) flatBonus += player._synergyBonusPwr;

    const rawAtk = baseAtk + flatBonus;

    // 3. Porcentaje de Buffs
    let buffPct = 0;
    const gs = window.gameState;
    if (gs && gs.playerStreak >= 3) {
      buffPct += 1.0;
    } else if (gs && gs.playerStreak === 2) {
      buffPct += 0.5;
    }
    if (player._spadesVorpalBonus && (score === 20 || score === 21)) {
      buffPct += player._spadesVorpalBonus;
    }
    if (typeof hasStarterBlessing === "function" && hasStarterBlessing("berserker_rage") && (score === 20 || score === 21)) {
      buffPct += 0.30;
    }
    const buffMultiplier = Math.max(0.1, 1 + buffPct);

    // 4. Doblar
    const doubleMult = (isDouble || player.turnDoubleDamage) ? 2.0 : 1.0;

    // Mitigación por Defensa Rival
    const effectiveEnemyDef = enemy ? Math.max(0, (enemy.def || 0) - (player.sharpArmorPierce || 0)) : 0;

    // Ataque Normal (Crítico x1.0)
    const normalAttack = Math.round(rawAtk * buffMultiplier * doubleMult);
    const minDmg = Math.max(0, normalAttack - effectiveEnemyDef);

    // Ataque Crítico (Crítico x2.0 / x2.5 BJ)
    const critMult = 2.0;
    const critAttack = Math.round(rawAtk * buffMultiplier * doubleMult * critMult);
    const maxDmg = Math.max(0, critAttack - effectiveEnemyDef);

    const critChance = (typeof recalculatePlayerStats === "function" ? (recalculatePlayerStats(player), player.critChance) : player.critChance) || 0;
    const prefix = (doubleMult > 1.0) ? "⚡ ATAQUE x2:" : "⚔️ ATAQUE:";
    const label = `${prefix} ${minDmg}`;

    return {
      minDmg,
      maxDmg,
      text: label,
      score,
      baseAtk,
      flatBonus,
      rawAtk,
      buffMultiplier,
      doubleMult,
      effectiveEnemyDef
    };
  }
  window.calculateTacticalAttackRange = calculateTacticalAttackRange;

  function showCombatCritSignal(multiplier = 1.5) {
    // v1.8.3: Suprimido el cartel ovalado flotante central (x2) para evitar superposición con los badges y tarjetas de perks
    return;
  }
  window.showCombatCritSignal = showCombatCritSignal;

  function calculateProjectedDamage(playerPwr, rivalDef, playerHand = [], deck = []) {
    const curScore = calculateHandScore(playerHand);
    if (curScore > 21) return { currentDmg: 0, crit21Dmg: 0 };
    const mockP = { pwr: playerPwr || 14, level: 1, currentBet: 0 };
    const mockE = { def: rivalDef || 0 };
    const exactCurrent = calculateExactTacticalDamage(mockP, mockE, playerHand, false);
    return {
      currentDmg: exactCurrent.dmg,
      crit21Dmg: Math.round(exactCurrent.dmg * 2.0)
    };
  }
  window.calculateProjectedDamage = calculateProjectedDamage;

  function explainTacticalOdds(type) {
    if (type === "crit") {
      showGameAlert(
        "⚡ PROBABILIDAD DE GOLPE CRÍTICO\n\n" +
        "Indica la probabilidad de asestar un Golpe Crítico demoledor (daño x2.0).\n\n" +
        "¿CÓMO POTENCIAR TU CRÍTICO?\n" +
        "1. 🌳 ÁRBOL DE TALENTOS: Invierte en la 'Rama del Filo' (Picas) para ganar probabilidad crítica y daño vorpal permanente.\n" +
        "2. 🃏 COMBINACIÓN DE CARTAS: Lograr 21 o Blackjack garantiza un 100% de Golpe Crítico.\n" +
        "3. 🔮 SELLOS ARCANOS: Graba Sellos de Picas y Sobrecarga para forzar impactos vorpales.",
        "TÁCTICA: GOLPE CRÍTICO"
      );
    } else if (type === "dmg") {
      showGameAlert(
        "⚔️ CÁLCULO DE ATAQUE EN TIEMPO REAL\n\n" +
        "Muestra el daño exacto que infligirás al ganar la mano de Blackjack:\n\n" +
        "• FÓRMULA DIRECTA: (Ataque Base + Bonos de Cartas/Sellos/Afinidades) * Buffs - DEF Rival.\n" +
        "• ¡Las cartas suman puntos para ganar la ronda de Blackjack, pero nunca se suman como daño!\n" +
        "• La píldora ⚡ CRÍTICO a la izquierda muestra tu probabilidad porcentual exacta de asestar un crítico (daño x2.0).\n" +
        "• Al pulsar '¡DOBLAR!', tu ataque se duplica x2 automáticamente.",
        "TÁCTICA: PODER DE ATAQUE"
      );
    }
  }
  window.explainTacticalOdds = explainTacticalOdds;

  function updateTacticalOddsHUD(zone = "tower") {
    try {
      if (zone === "tower") {
        const hud = document.getElementById("dnd-tactical-odds-hud");
        if (!hud) return;
        const p = (window.gameState && window.gameState.player);
        const e = (window.gameState && window.gameState.enemy);
        if (!p || !p.playerHand) return;
        const curScore = calculateHandScore(p.playerHand);

        const critEl = document.getElementById("dnd-crit-odds");
        const dmgEl = document.getElementById("dnd-projected-dmg");

        // 1. Probabilidad predictiva exacta de Crítico basada en las estadísticas reales del héroe
        let critText = "";
        if (curScore > 21) {
          critText = `💀 BUST (0%)`;
        } else {
          if (typeof recalculatePlayerStats === "function") recalculatePlayerStats(p);
          const totalCrit = (typeof p.critChance === "number") ? p.critChance : 0;
          critText = `⚡ CRÍTICO: ${totalCrit}%`;
        }

        // 2. Poder de golpe actual exacto en tiempo real (Bloque 4)
        const isDoubled = !!(p && p.turnDoubleDamage);
        const rangeData = calculateTacticalAttackRange(p, e, p.playerHand, isDoubled);

        if (critEl) {
          critEl.style.display = "inline-flex";
          critEl.innerText = critText;
        }
        if (dmgEl) {
          dmgEl.style.display = "inline-flex";
          dmgEl.innerText = rangeData.text;
        }
      } else if (zone === "arena") {
        const hud = document.getElementById("arena-dnd-odds-hud");
        if (!hud || !window.arenaMatch) return;
        const hand = window.arenaMatch.playerHand || [];
        const curScore = calculateHandScore(hand);
        const pwr = (window.arenaMatch.playerStats && window.arenaMatch.playerStats.pwr) || 16;
        const def = (window.arenaMatch.rival && window.arenaMatch.rival.def) || 6;
        const mockP = { pwr, def: (window.arenaMatch.playerStats && window.arenaMatch.playerStats.def) || 3, critChance: 25 };
        const mockE = { def };
        const isDoubledArena = !!(window.arenaMatch && window.arenaMatch.isDoubled);
        const rangeData = calculateTacticalAttackRange(mockP, mockE, hand, isDoubledArena);

        const critEl = document.getElementById("arena-dnd-crit-odds");
        const dmgEl = document.getElementById("arena-dnd-projected-dmg");

        if (critEl) {
          critEl.style.display = "inline-flex";
          if (curScore >= 19 && curScore <= 21) {
            critEl.innerText = `⚡ CRÍTICO: 100% (ACTIVO)`;
          } else {
            critEl.innerText = `⚡ CRÍTICO: 25%`;
          }
        }
        if (dmgEl) {
          dmgEl.style.display = "inline-flex";
          dmgEl.innerText = rangeData.text;
        }
      }
    } catch (_) {}
  }
  window.updateTacticalOddsHUD = updateTacticalOddsHUD;


  function getMasteryBonuses(masteryLevel) {
    const bonusLvl = Math.max(0, (masteryLevel || 1) - 1);
    return {
      hp: bonusLvl * 6,
      pwr: Math.floor(bonusLvl / 2),
      def: Math.floor(bonusLvl / 3),
      gold: bonusLvl * 15,
      potions: bonusLvl >= 1 ? 1 : 0,
      rerolls: bonusLvl >= 2 ? 1 : 0,
      startingSeal: bonusLvl >= 3
    };
  }

  function addHeroPermanentExp(heroClass, amount) {
    if (!heroClass) return;
    const meta = getHeroMeta();
    if (!meta[heroClass]) {
      meta[heroClass] = { totalExp: 0, masteryLevel: 1, level: 1, exp: 0, runs: 0, wins: 0, prestigeTrophies: 0 };
    }
    if (amount > 0 && typeof isRoyalPerkOwned === "function" && isRoyalPerkOwned("exp_boost")) {
      amount = Math.round(amount * 1.5);
    }
    meta[heroClass].totalExp = (meta[heroClass].totalExp || 0) + amount;
    // SPRINT 1: el Nivel de Maestría y el Nivel de Run son el MISMO Nivel Permanente Real
    meta[heroClass].masteryLevel = meta[heroClass].level || meta[heroClass].masteryLevel || 1;
    saveHeroMeta(meta);
    updateHeroSelectUI();
  }

