  const CAMPAIGN_WAYPOINTS_KEY = "bj_campaign_waypoints_v1";

  function getCampaignWaypoints() {
    try {
      const raw = localStorage.getItem(CAMPAIGN_WAYPOINTS_KEY);
      if (raw) return JSON.parse(raw);
    } catch (_) {}
    return { normal: 1, hard: 1, mythic: 1, nightmare: 1, hell: 1 };
  }
  window.getCampaignWaypoints = getCampaignWaypoints;

  function unlockCampaignWaypoint(diffKey, chapterNum) {
    const wp = getCampaignWaypoints();
    if (!wp[diffKey] || chapterNum > wp[diffKey]) {
      wp[diffKey] = Math.min(7, Math.max(wp[diffKey] || 1, chapterNum));
      try { localStorage.setItem(CAMPAIGN_WAYPOINTS_KEY, JSON.stringify(wp)); } catch (_) {}
    }
    return wp;
  }
  window.unlockCampaignWaypoint = unlockCampaignWaypoint;

  function autoHealCampaignWaypointsForFloor(floor, diffKey = "normal") {
    const diff = diffKey || (typeof getGameDifficulty === "function" ? getGameDifficulty() : "normal");
    const wp = getCampaignWaypoints();
    let targetWaypoint = wp[diff] || 1;

    // Verificar si la dificultad ya tiene la campaña completada o victorias previas en la torre
    const campaignDiffWon = (localStorage.getItem(`bj_campaign_completed_${diff}`) === "true");
    const towerWinsOnDiff = parseInt(localStorage.getItem(`bj_victory_knight_${diff}`) || "0", 10) +
                            parseInt(localStorage.getItem(`bj_victory_mage_${diff}`) || "0", 10) +
                            parseInt(localStorage.getItem(`bj_victory_rogue_${diff}`) || "0", 10) +
                            parseInt(localStorage.getItem(`bj_victory_paladin_${diff}`) || "0", 10) +
                            parseInt(localStorage.getItem(`bj_victory_necro_${diff}`) || "0", 10);
    if (campaignDiffWon || towerWinsOnDiff > 0) {
      targetWaypoint = Math.max(targetWaypoint, 7);
    }

    if (floor && floor >= 1) {
      if (floor >= 22) targetWaypoint = Math.max(targetWaypoint, 7);
      else if (floor >= 20) targetWaypoint = Math.max(targetWaypoint, 6);
      else if (floor >= 16) targetWaypoint = Math.max(targetWaypoint, 5);
      else if (floor >= 12) targetWaypoint = Math.max(targetWaypoint, 4);
      else if (floor >= 8) targetWaypoint = Math.max(targetWaypoint, 3);
      else if (floor >= 4) targetWaypoint = Math.max(targetWaypoint, 2);
    }

    if (targetWaypoint > (wp[diff] || 1)) {
      unlockCampaignWaypoint(diff, targetWaypoint);
    }
  }
  window.autoHealCampaignWaypointsForFloor = autoHealCampaignWaypointsForFloor;

  function autoHealAllCampaignWaypoints() {
    const diffs = ["normal", "hard", "mythic", "nightmare", "hell"];
    try {
      const savedRun = JSON.parse(localStorage.getItem(MID_RUN_STORAGE_KEY) || "null");
      diffs.forEach(d => {
        const floorToHeal = (savedRun && (savedRun.diff === d || (!savedRun.diff && d === "normal"))) ? savedRun.floor : 1;
        autoHealCampaignWaypointsForFloor(floorToHeal, d);
      });
    } catch (_) {
      diffs.forEach(d => autoHealCampaignWaypointsForFloor(1, d));
    }
    if (typeof renderCampaignChaptersUI === "function") {
      renderCampaignChaptersUI();
    }
  }
  window.autoHealAllCampaignWaypoints = autoHealAllCampaignWaypoints;

  function startCampaignRun(diffKey, chapterNum = 1) {
    const wp = getCampaignWaypoints();
    const maxWp = wp[diffKey] || 1;
    if (chapterNum > maxWp) {
      if (typeof spawnFloatingText === "function") {
        spawnFloatingText("hero-book-stage", `🔒 Acto ${chapterNum} bloqueado. Supera los anteriores.`, "crit");
      }
      try { playBustSound(); } catch (_) {}
      return false;
    }
    const curChapter = CAMPAIGN_CHAPTERS.find(c => c.number === chapterNum) || CAMPAIGN_CHAPTERS[0];
    const startFloor = curChapter.startFloor || 1;
    const curHeroKey = (typeof HERO_KEYS !== "undefined" && typeof heroBookIndex === "number" && HERO_KEYS[heroBookIndex]) ? HERO_KEYS[heroBookIndex] : "knight";

    const launchRun = () => {
      setGameDifficulty(diffKey);
      gameState.isCampaignMode = true;
      gameState.chapter = chapterNum;
      gameState.floor = startFloor;
      startGame(curHeroKey, false, startFloor, chapterNum);
    };

    if (typeof showGameConfirm === "function") {
      showGameConfirm({
        title: `🗺️ INICIAR ACTO ${chapterNum}`,
        message: `¿Deseas iniciar tu expedición en "${curChapter.name}" (Piso ${startFloor}) con tu héroe actual?`,
        okLabel: "⚡ ENTRAR AL ACTO",
        cancelLabel: "◀ VOLVER",
        onConfirm: launchRun,
        onCancel: () => {
          const panel = document.getElementById("campaign-chapters-panel");
          if (panel) {
            panel.classList.remove("hidden");
            panel.style.display = "";
          }
          const grid = document.getElementById("campaign-chapters-grid");
          if (grid) {
            grid.classList.remove("hidden");
            grid.style.display = "";
          }
          renderCampaignChaptersUI();
        }
      });
      return true;
    }

    launchRun();
    return true;
  }
  window.startCampaignRun = startCampaignRun;

  function renderCampaignChaptersUI() {
    const panel = document.getElementById("campaign-chapters-panel");
    if (panel) {
      panel.classList.remove("hidden");
      panel.style.display = "";
    }
    const grid = document.getElementById("campaign-chapters-grid");
    if (!grid) return;
    grid.classList.remove("hidden");
    grid.style.display = "grid";
    const curDiff = (typeof getGameDifficulty === "function") ? getGameDifficulty() : "normal";
    const wp = getCampaignWaypoints();
    const highestWp = wp[curDiff] || 1;

    grid.innerHTML = CAMPAIGN_CHAPTERS.map(ch => {
      const isUnlocked = ch.number <= highestWp;
      const isCompleted = ch.number < highestWp;
      const statusClass = isCompleted ? "completed" : (isUnlocked ? "unlocked" : "locked");
      const statusText = isCompleted ? "✔ VENCIDO" : (isUnlocked ? "⚡ ENTRANTE" : "🔒 BLOQUEADO");
      const floorRange = (ch.startFloor && ch.endFloor) ? `P.${ch.startFloor}-${ch.endFloor}` : `Acto ${ch.number}`;

      return `
        <div class="campaign-chapter-card ${statusClass}" onclick="startCampaignRun('${curDiff}', ${ch.number})" title="Acto ${ch.number}: ${ch.name} (${floorRange})">
          <div class="campaign-ch-num">${ch.suit} ACTO ${ch.number}</div>
          <div class="campaign-ch-name">${ch.name}</div>
          <div class="campaign-ch-boss">Jefe: ${ch.bossName.split(' ')[0]} (${floorRange})</div>
          <div class="campaign-ch-wp">${statusText}</div>
        </div>
      `;
    }).join("");
  }
  window.renderCampaignChaptersUI = renderCampaignChaptersUI;

  function toggleCampaignChapters(show) {
    const panel = document.getElementById("campaign-chapters-panel");
    if (!panel) return;
    panel.classList.remove("hidden");
    panel.style.display = "";
    const grid = document.getElementById("campaign-chapters-grid");
    if (grid) {
      grid.classList.remove("hidden");
      grid.style.display = "grid";
    }
    renderCampaignChaptersUI();
  }
  window.toggleCampaignChapters = toggleCampaignChapters;

