  function getEnemyTraitDescription(e) {
    if (e.trait === "thief") return "Robo: Si el rival gana la mano, te roba 5 de oro.";
    if (e.trait === "undead") return "Resurrección: Al caer a 0 HP, revive inmediatamente una vez con 15 HP.";
    if (e.trait === "fury") return "Furia: Cada vez que recibe daño, su ira aumenta (+1 PWR permanente).";
    if (e.trait === "stone") return "Piel Pétrea: Su corteza de granito anula y bloquea todo golpe de ≤ 3 de daño.";
    if (e.trait === "stealth") return "Sigilo: Juega con cartas totalmente ocultas hasta que se planta.";
    if (e.trait === "disciplined") return "Disciplina: No se planta jamás hasta alcanzar 18 o más puntos.";
    if (e.trait === "thorns") return "Espinas: Devuelve 1 de daño directo al atacante cada vez que es golpeado.";
    if (e.trait === "dragon") return "Aliento Ígneo: Quema 3 HP cada 2 manos y su Blackjack inflige daño triple (x3).";
    return e.traitName || "Sin rasgo especial activo.";
  }

  function getItemSpanishName(item) {
    if (!item) return "";
    if (typeof item === "object") {
      return item.name ? `${item.icon || '🔮'} ${item.name}` : (item.id || "");
    }
    const id = String(item);
    const dict = {
      mercury_band: "💫 Brazalete de Mercurio (+2 PWR, +1 DEF)",
      ruby: "🔴 Rubí Ígneo (+2 daño en manos impares)",
      sapphire: "🔵 Zafiro Guardián (+5 Escudo al iniciar piso)",
      emerald: "🟢 Esmeralda del Destino (+1 PWR permanente)",
      topaz: "🟡 Topacio Radiante (+1 de daño)",
      blackjack_gem: "💎 Joya de Blackjack (+5 daño, +15 HP)",
      blackjack_heritage: "👑 Joya Heredada (+3 PWR, +10% Crítico, +16 HP)",
      blood_amulet: "🩸 Amuleto de Sangre (+6 HP al derrotar rival)",
      amber_amulet: "🟠 Amuleto Ámbar (+1 HP por piso)",
      lucky_charm: "🍀 Amuleto de la Suerte (25% evitar daño, +10% Suerte)",
      spiked_belt: "🌵 Cinturón con Púas (+1 Daño Espinas directo)",
      lead_gauntlet: "🥊 Guante de Plomo (Cartas bajas valen mín. 3)",
      steel_helm: "🪖 Casco de Acero (+1 DEF)",
      rider_spur: "👞 Espuela de Celeridad (+8 daño, +15 oro en 1ª mano)",
      warriors_ring: "💍 Anillo del Guerrero (+3 daño base)",
      fury_bracer: "🥊 Brazal de Furia (+daño por racha)",
      bloody_chalice: "🍷 Cáliz Ensangrentado (+10% Vampirismo)",
      blood_chalice: "🍷 Cáliz de Sangre (+10% Vampirismo)",
      titan_heart: "❤️ Corazón de Titán (+4 HP por mano)",
      holy_grail: "🏆 Cáliz del 21 (+10 daño, +10 HP en Blackjack)",
      bone_die: "🎲 Dado de Hueso (+1 Reroll por piso)",
      infinity_ring: "♾️ Anillo Infinito (+2 Rerolls por piso)",
      eternal_potion: "🧪 Poción Eterna (Poción de emergencia)",
      easter_bell: "🔔 Campana de Pascua (Inmunidad a Veneno/Fuego)",
      guardian_quartz: "🛡️ Cuarzo Guardián (+6 Escudo por piso)",
      diamond_aegis: "💎 Égida de Diamante (+10 Escudo por piso)",
      golden_die: "🎲 Dado de Oro (+3 daño permanente)",
      sharp_blade: "🗡️ Filo Afilado (+10% Crítico)",
      shadow_cloak: "🧥 Capa de Sombras (+10% Esquivar)",
      wind_cloak: "💨 Manto del Viento (+10% Esquivar)",
      lucky_coin: "🪙 Moneda de la Suerte (+10% Suerte)",
      thorn_crown: "👑 Corona de Espinas (+5 Espinas)",
      mirror_shield: "🪞 Escudo Espejo (+5 Espinas, +30% Reflejo)",
      hourglass: "⏳ Reloj de Arena (+Tiempo de turno y concentración)",
      hourglass_time: "⏳ Reloj de Arena (+Tiempo de turno)",
      relic_hourglass: "⏳ Reloj de Arena (+Tiempo de turno y concentración)",
      relic_dante_blade: "🗡️ Filo Sangriento de Dante (+3 PWR, 2 Veneno)",
      relic_dante_spades: "♠️ Cota de Picas del Conquistador (+2 DEF, +2 Escudo por ♠)",
      relic_dante_blood: "🩸 Frasco de Sangre Pura (+25 HP Máx, 2 Pociones)",
      relic_valk_aegis: "🛡️ Baluarte de Diamantes (+10 Escudo por mano)",
      relic_valk_light: "✨ Relicario de la Luz (+3 PWR, +6 HP en 19/20)",
      relic_valk_core: "💎 Núcleo Diamantino (+3 DEF, +2 Rerolls)",
      relic_archmage_eye: "🔮 Ojo Arcano del Archimago (+4 PWR, Sello Cósmico)",
      relic_archmage_veil: "🌌 Manto del Vacío (25% Evitar contraataque)",
      relic_archmage_mana: "⚡ Cáliz de Éter (Overdrive inicial, +40 Oro)",
      relic_necro_harvest: "💀 Cosecha de Malfas (35% Curar +4 HP)",
      relic_necro_scythe: "☠️ Guadaña del Segador (+5 PWR, x3 Blackjack)",
      relic_necro_bones: "🦴 Coraza de Huesos Malditos (+4 DEF, +3 Espinas)",
      relic_shadow_mirror: "🎭 Espejo de Sombras del 21 (Anula 1 BUST)",
      relic_shadow_crown: "👑 Corona del Gran Tahúr (+60 Oro, +4 PWR, +3 DEF)",
      relic_shadow_pact: "⚔️ Pacto del Vencedor Inmortal (Inmunidad Asalto Muerte)"
    };
    if (dict[id]) return dict[id];
    const strippedId = id.replace(/^relic_/, '');
    if (dict[strippedId]) return dict[strippedId];

    if (typeof ALL_RELICS !== "undefined") {
      const found = ALL_RELICS.find(r => r.id === id || r.id === strippedId);
      if (found) return `${found.icon || '🔮'} ${found.name}`;
    }
    if (typeof SHOP_ARTIFACTS !== "undefined") {
      const foundShop = SHOP_ARTIFACTS.find(r => r.id === id || r.id === strippedId);
      if (foundShop) return `${foundShop.icon || '🔮'} ${foundShop.name}`;
    }
    if (typeof DEMONIC_RELICS_BY_ACT !== "undefined") {
      for (const pool of Object.values(DEMONIC_RELICS_BY_ACT)) {
        const foundDemonic = pool.find(r => r.id === id || r.id === strippedId);
        if (foundDemonic) return `${foundDemonic.icon || '👹'} ${foundDemonic.name}`;
      }
    }
    if (typeof ITEM_INFO !== "undefined" && ITEM_INFO[id]) {
      return ITEM_INFO[id].split(':')[0];
    }
    const clean = strippedId.replace(/_/g, ' ');
    return clean.charAt(0).toUpperCase() + clean.slice(1);
  }
  window.getItemSpanishName = getItemSpanishName;

  function openFighterInspect(who = "player") {
    if (window.__isSwiping) return;
    const p = gameState.player;
    const e = gameState.enemy;
    const modal = document.getElementById("screen-inspect");
    if (!modal) return;

    const avatarBox = document.getElementById("inspect-avatar-container");
    const nameEl = document.getElementById("inspect-name");
    const subEl = document.getElementById("inspect-subtitle");
    const currBox = document.getElementById("inspect-currencies");
    const tbody = document.getElementById("inspect-stats-tbody");
    const activeItemsEl = document.getElementById("inspect-active-items");
    const activeItemsSec = document.getElementById("inspect-active-items-section");
    const statusEl = document.getElementById("inspect-status");

    if (who === "player") {
      if (typeof recalculatePlayerStats === "function") recalculatePlayerStats(p);
      const hero = HERO_DATA[p.class] || HERO_DATA.knight;
      const meta = (typeof getHeroMeta === "function") ? getHeroMeta() : {};
      const hMeta = meta[p.class] || { totalExp: 0, masteryLevel: 1 };
      nameEl.innerText = (p.name || hero.name).toUpperCase();
      nameEl.style.color = "#66fcf1";
      subEl.innerText = `⭐ NIVEL PERMANENTE ${hMeta.level || hMeta.masteryLevel || 1} • ${hMeta.exp || 0}/${(typeof getExpRequiredForLevel === "function") ? getExpRequiredForLevel(hMeta.level || hMeta.masteryLevel || 1) : 60} EXP • ${hMeta.totalExp || 0} EXP TOTAL`;

      if (hero.img) {
        avatarBox.innerHTML = `<img src="${hero.img}" alt="${hero.name}" onerror="this.outerHTML='${hero.sprite}'">`;
      } else {
        avatarBox.innerText = hero.sprite;
      }
      avatarBox.style.borderColor = "#66fcf1";

      // Monedas de la run activa
      if (currBox) {
        const cryptCoins = (typeof getPlayerCryptCoins === "function") ? getPlayerCryptCoins() : (parseInt(localStorage.getItem("bj_crypt_coins") || "0", 10));
        currBox.innerHTML = `
          <div style="background:rgba(255,209,102,0.12);border:1px solid rgba(255,209,102,0.3);border-radius:6px;padding:4px 8px;font-size:10px;font-weight:bold;color:#ffd166;display:flex;align-items:center;gap:4px;">
            🪙 ${gameState.gold || p.gold || 0} ORO
          </div>
          <div style="background:rgba(102,252,241,0.12);border:1px solid rgba(102,252,241,0.3);border-radius:6px;padding:4px 8px;font-size:10px;font-weight:bold;color:#66fcf1;display:flex;align-items:center;gap:4px;">
            💀 ${cryptCoins} CRIPTA
          </div>
          <div style="background:rgba(230,57,70,0.12);border:1px solid rgba(230,57,70,0.3);border-radius:6px;padding:4px 8px;font-size:10px;font-weight:bold;color:#ff758f;display:flex;align-items:center;gap:4px;">
            🧪 ${p.potions || 0} POCIONES
          </div>
        `;
      }

      // Cálculo de Estadísticas en Vivo: Base vs Buff/Nerf vs Total
      const baseHp = hero.hp || 80;
      const hpDiff = p.maxHp - baseHp;
      const hpBuffStr = hpDiff > 0 ? `<b style="color:#2a9d8f;">+${hpDiff}</b>` : (hpDiff < 0 ? `<b style="color:#e63946;">${hpDiff}</b>` : "--");

      const basePwr = hero.pwr || 2;
      let pwrBuffVal = p.pwr - basePwr;
      let pwrBuffParts = [];
      if (pwrBuffVal !== 0) pwrBuffParts.push(pwrBuffVal > 0 ? `+${pwrBuffVal}` : `${pwrBuffVal}`);
      if (p.turnDoubleDamage) pwrBuffParts.push("x2 Mano");
      if (p.hasGoldenDie) pwrBuffParts.push("+3 Dado");
      const pwrBuffStr = pwrBuffParts.length ? `<b style="color:#2a9d8f;">${pwrBuffParts.join(", ")}</b>` : "--";
      const totalEffectivePwr = (p.pwr * (p.turnDoubleDamage ? 2 : 1)) + (p.hasGoldenDie ? 3 : 0);

      const baseDef = hero.def || 0;
      const effDef = (p.def || 0) + (p.turnShieldBonus || 0) + (p.duplaDef || 0) + (p._synergyBonusDef || 0);
      const defDiff = effDef - baseDef;
      let defBuffParts = [];
      if (p.turnShieldBonus > 0) defBuffParts.push(`+${p.turnShieldBonus} Pasiva`);
      if (p.duplaDef > 0) defBuffParts.push(`+${p.duplaDef} Dupla`);
      if ((p._synergyBonusDef || 0) > 0) defBuffParts.push(`+${p._synergyBonusDef} Perk`);
      const defBuffStr = defBuffParts.length ? `<b style="color:#2a9d8f;">${defBuffParts.join(", ")}</b>` : (defDiff > 0 ? `<b style="color:#2a9d8f;">+${defDiff}</b>` : "--");

      const pShield = gameState.status.playerShield || 0;
      const pMaxShield = Math.max(pShield, 10 + effDef);
      const shieldBuffStr = pShield > 0 ? `<b style="color:#48cae4;">+${pShield}</b>` : "--";

      const baseCrit = hero.critChance || 0;
      const critDiff = (p.critChance || 0) - baseCrit;
      const critBuffStr = critDiff > 0 ? `<b style="color:#2a9d8f;">+${critDiff}%</b>` : "--";

      const baseDodge = hero.dodgeChance || 0;
      const dodgeBonus = Math.round((p._synergyExtraDodge || 0) * 100);
      const totalDodge = Math.min(45, (p.dodgeChance || 0) + dodgeBonus);
      const dodgeDiff = totalDodge - baseDodge;
      const dodgeBuffStr = dodgeDiff > 0 ? `<b style="color:#2a9d8f;">+${dodgeDiff}%</b>` : "--";

      const baseThorns = hero.thorns || 0;
      const thornsVal = p.thorns || 0;
      const thornsDiff = thornsVal - baseThorns;
      const thornsBuffStr = thornsDiff > 0 ? `<b style="color:#2a9d8f;">+${thornsDiff}</b>` : (thornsDiff < 0 ? `<b style="color:#e63946;">${thornsDiff}</b>` : "--");

      const baseLifesteal = hero.lifesteal || 0;
      const lifestealVal = p.lifesteal || 0;
      const lifestealDiff = lifestealVal - baseLifesteal;
      const lifestealBuffStr = lifestealDiff > 0 ? `<b style="color:#2a9d8f;">+${lifestealDiff}%</b>` : (lifestealDiff < 0 ? `<b style="color:#e63946;">${lifestealDiff}%</b>` : "--");

      const baseLuck = hero.luck || 0;
      const luckVal = p.luck || 0;
      const luckDiff = luckVal - baseLuck;
      const luckBuffStr = luckDiff > 0 ? `<b style="color:#2a9d8f;">+${luckDiff}%</b>` : (luckDiff < 0 ? `<b style="color:#e63946;">${luckDiff}%</b>` : "--");

      // Renderizar tabla en tbody
      if (tbody) {
        tbody.innerHTML = `
          <tr>
            <td><span class="stat-ico">❤️</span> <b>Salud (HP)</b></td>
            <td>${baseHp}</td>
            <td>${hpBuffStr}</td>
            <td style="text-align:right;font-weight:bold;color:#2a9d8f;">${p.hp} / ${p.maxHp}</td>
          </tr>
          <tr>
            <td><span class="stat-ico">⚔️</span> <b>Poder (Ataque)</b></td>
            <td>${basePwr}</td>
            <td>${pwrBuffStr}</td>
            <td style="text-align:right;font-weight:bold;color:#ffd166;">${totalEffectivePwr}</td>
          </tr>
          <tr>
            <td><span class="stat-ico">🛡️</span> <b>Defensa (DEF)</b></td>
            <td>${baseDef}</td>
            <td>${defBuffStr}</td>
            <td style="text-align:right;font-weight:bold;color:#66fcf1;">${effDef}</td>
          </tr>
          <tr>
            <td><span class="stat-ico">🛡️</span> <b>Escudo Activo</b></td>
            <td>0</td>
            <td>${shieldBuffStr}</td>
            <td style="text-align:right;font-weight:bold;color:#48cae4;">${pShield} / ${pMaxShield}</td>
          </tr>
          <tr>
            <td><span class="stat-ico">⚡</span> <b>% Golpe Crítico</b></td>
            <td>${baseCrit}%</td>
            <td>${critBuffStr}</td>
            <td style="text-align:right;font-weight:bold;color:#f39c12;">${p.critChance || 0}%</td>
          </tr>
          <tr>
            <td><span class="stat-ico">💨</span> <b>% Esquiva (Dodge)</b></td>
            <td>${baseDodge}%</td>
            <td>${dodgeBuffStr}</td>
            <td style="text-align:right;font-weight:bold;color:#38bdf8;">${totalDodge}%</td>
          </tr>
          <tr>
            <td><span class="stat-ico">🌵</span> <b>Espinas (Daño Puro)</b></td>
            <td>${baseThorns}</td>
            <td>${thornsBuffStr}</td>
            <td style="text-align:right;font-weight:bold;color:#10b981;">${thornsVal}</td>
          </tr>
          <tr>
            <td><span class="stat-ico">🩸</span> <b>% Vampirismo</b></td>
            <td>${baseLifesteal}%</td>
            <td>${lifestealBuffStr}</td>
            <td style="text-align:right;font-weight:bold;color:#e63946;">${lifestealVal}%</td>
          </tr>
          <tr>
            <td><span class="stat-ico">🍀</span> <b>% Suerte (Luck)</b></td>
            <td>${baseLuck}%</td>
            <td>${luckBuffStr}</td>
            <td style="text-align:right;font-weight:bold;color:#a3e635;">${luckVal}%</td>
          </tr>
        `;
      }

      // Elementos Activos en la Run
      if (activeItemsSec) activeItemsSec.style.display = "block";
      if (activeItemsEl) {
        let itemsList = [];
        if (p.starterBlessing) {
          const b = p.starterBlessing;
          itemsList.push(`<div>✨ <b>Bendición del Destino [${b.tierLabel || ('Tier ' + b.tier)}]:</b> ${b.icon || '✨'} ${b.name} — <span style="color:#ffd166;">${b.desc}</span></div>`);
        }
        if (p.gem) {
          itemsList.push(`<div>💎 <b>Gema Engarzada:</b> ${getItemSpanishName(p.gem)}.</div>`);
        }
        if (p.accessory) {
          itemsList.push(`<div>💍 <b>Accesorio:</b> ${getItemSpanishName(p.accessory)}.</div>`);
        }
        if (p.weapon) {
          itemsList.push(`<div>🗡️ <b>Arma:</b> ${getItemSpanishName(p.weapon)}.</div>`);
        }
        if (p.relics && p.relics.length > 0) {
          const relStr = p.relics.map(r => getItemSpanishName(r)).join(", ");
          itemsList.push(`<div>🔮 <b>Reliquias Arcanas (${p.relics.length}):</b> ${relStr}.</div>`);
        }
        if (p.artifacts && p.artifacts.length > 0) {
          const artStr = p.artifacts.map(a => getItemSpanishName(a)).join(", ");
          itemsList.push(`<div>🏺 <b>Artefactos de Poder (${p.artifacts.length}):</b> ${artStr}.</div>`);
        }
        if (p.cardUpgrades && p.cardUpgrades.length > 0) {
          const uList = p.cardUpgrades.map(id => {
            const u = CARD_UPGRADES.find(c => c.id === id);
            return u ? `${u.icon} ${u.name}` : id;
          });
          itemsList.push(`<div>🔨 <b>Pasivas de Forja del Yunque:</b> ${uList.join(", ")}.</div>`);
        }
        if (p.curse) {
          itemsList.push(`<div style="color:#e63946;">🩸 <b>Maldición del Abismo:</b> ${CURSE_NAMES[p.curse] || (p.curse === "cursed_deck" ? "Mazo Astillado (-5 HP por cada As)" : p.curse)}.</div>`);
        }
        activeItemsEl.innerHTML = itemsList.length ? itemsList.join("") : "<div style='color:#94a3b8;'>Ningún equipamiento ni bendición especial activa.</div>";
      }

      // Estados Alterados y Perks de Turno en Combate
      let statusList = [];
      if (gameState.status.playerShield > 0) statusList.push(`🛡️ <b>Escudo Protector:</b> ${gameState.status.playerShield} HP de daño que serán absorbidos antes de tu vida.`);
      if ((p._synergyBonusDef || 0) > 0) statusList.push(`🛡️ <b>Perk [Muralla de Hierro]:</b> +${p._synergyBonusDef} DEF frente al próximo contraataque.`);
      if (p._synergyExtraDodge > 0) statusList.push(`💨 <b>Perk [Acto de Desaparición]:</b> ${Math.round(p._synergyExtraDodge * 100)}% de esquivar el próximo contraataque.`);
      if (p._synergyLastStand) statusList.push(`🏰 <b>Perk [Última Resistencia]:</b> El próximo golpe rival se reduce a 1 punto de daño.`);
      if (p.turnDoubleDamage) statusList.push(`⚡ <b>Golpe Traicionero x2:</b> Tu ataque en esta mano infligirá el doble de daño.`);
      if (p.duplaDef > 0) statusList.push(`⚡ <b>Dupla de Mano:</b> +${p.duplaDef} DEF activa en esta ronda por pareja de cartas.`);
      if (gameState.status.playerPoison > 0) statusList.push(`☠️ <b>Veneno Activo:</b> ${gameState.status.playerPoison} de daño directo al inicio del siguiente turno.`);
      if (gameState.status.playerBurn > 0) statusList.push(`🔥 <b>Quemadura Ígnea:</b> ${gameState.status.playerBurn} de daño por fuego activo.`);

      statusEl.innerHTML = statusList.length ? statusList.join("<br>") : "<div style='color:#94a3b8;'>Sin estados alterados temporales activos.</div>";

      // Cartas Arcanas Forjadas
      const encSection = document.getElementById("inspect-enchanted-section");
      const encGrid = document.getElementById("inspect-enchanted-grid");
      const encTitle = document.getElementById("inspect-enchanted-title");
      if (encSection && encGrid) {
        const enchantedMap = p.cardEnchantments || {};
        const enchantedKeys = Object.keys(enchantedMap);
        if (enchantedKeys.length > 0) {
          encSection.style.display = "block";
          if (encTitle) encTitle.innerText = `🃏 CARTAS FORJADAS EN BARAJA (${enchantedKeys.length}):`;
          encGrid.innerHTML = renderHandDeckFan(enchantedMap, "inspect-hand-deck-fan");
          setupHandFanInteractions("inspect-hand-deck-fan");
        } else {
          encSection.style.display = "none";
        }
      }

    } else {
      // INSPECCIÓN DEL RIVAL
      const encSection = document.getElementById("inspect-enchanted-section");
      if (encSection) encSection.style.display = "none";

      const maxF = (typeof getMaxFloorsForDifficulty === "function") ? getMaxFloorsForDifficulty() : 13;
      nameEl.innerText = (e.name || "RIVAL").toUpperCase();
      nameEl.style.color = "#ff758f";
      subEl.innerText = `PISO ${gameState.floor} / ${maxF} — RIVAL DE LA TORRE`;

      if (e.img) {
        avatarBox.innerHTML = `<img src="${e.img}" alt="${e.name}" onerror="this.outerHTML='${e.sprite || '👺'}'">`;
      } else {
        avatarBox.innerText = e.sprite || "👺";
      }
      avatarBox.style.borderColor = "#e63946";

      if (currBox) {
        currBox.innerHTML = `
          <div style="background:rgba(230,57,70,0.12);border:1px solid rgba(230,57,70,0.3);border-radius:6px;padding:4px 8px;font-size:10px;font-weight:bold;color:#ff758f;display:flex;align-items:center;gap:4px;">
            💀 DROP: CRIPTAS Y CARTAS COSMÉTICAS
          </div>
        `;
      }

      const eShield = gameState.status.enemyShield || 0;
      const eMaxShield = Math.max(eShield, (e && e.def ? e.def + 10 : 10));

      if (tbody) {
        tbody.innerHTML = `
          <tr>
            <td><span class="stat-ico">❤️</span> <b>Salud (HP)</b></td>
            <td>${e.maxHp}</td>
            <td>--</td>
            <td style="text-align:right;font-weight:bold;color:#e63946;">${e.hp} / ${e.maxHp}</td>
          </tr>
          <tr>
            <td><span class="stat-ico">⚔️</span> <b>Poder (Ataque)</b></td>
            <td>${e.pwr}</td>
            <td>--</td>
            <td style="text-align:right;font-weight:bold;color:#ffd166;">${e.pwr}</td>
          </tr>
          <tr>
            <td><span class="stat-ico">🛡️</span> <b>Defensa (DEF)</b></td>
            <td>${e.def}</td>
            <td>--</td>
            <td style="text-align:right;font-weight:bold;color:#66fcf1;">${e.def}</td>
          </tr>
          <tr>
            <td><span class="stat-ico">🛡️</span> <b>Escudo Activo</b></td>
            <td>0</td>
            <td>${eShield > 0 ? `<b style="color:#48cae4;">+${eShield}</b>` : '--'}</td>
            <td style="text-align:right;font-weight:bold;color:#48cae4;">${eShield} / ${eMaxShield}</td>
          </tr>
          <tr>
            <td><span class="stat-ico">🌵</span> <b>Espinas</b></td>
            <td>${e.trait === 'thorns' ? '2' : '0'}</td>
            <td>--</td>
            <td style="text-align:right;font-weight:bold;color:#10b981;">${e.trait === 'thorns' ? '2 daño' : '--'}</td>
          </tr>
        `;
      }

      if (activeItemsSec) activeItemsSec.style.display = "block";
      if (activeItemsEl) {
        activeItemsEl.innerHTML = `
          <div><b style="color:#ffd166;">★ Rasgo Especial [${e.traitName || e.traitShort || 'Rasgo'}]:</b> ${(typeof getEnemyTraitDescription === 'function') ? getEnemyTraitDescription(e) : (e.traitName || e.traitShort || 'Sin rasgo especial')}.</div>
        `;
      }

      let statusList = [];
      if (gameState.status.enemyShield > 0) statusList.push(`🛡️ <b>Escudo:</b> ${gameState.status.enemyShield} HP de protección que absorberán tus ataques.`);
      if (gameState.status.enemyPoison > 0) statusList.push(`☠️ <b>Veneno Residual:</b> ${gameState.status.enemyPoison} de daño al inicio del turno.`);
      if (gameState.status.enemyBurn > 0) statusList.push(`🔥 <b>Quemadura:</b> ${gameState.status.enemyBurn} de daño residual.`);
      if (gameState.status.enemyRevived) statusList.push(`💀 <b>Resurrección Maldita:</b> Ya utilizada en este asalto.`);

      statusEl.innerHTML = statusList.length ? statusList.join("<br>") : "<div style='color:#94a3b8;'>Sin estados alterados residuales.</div>";
    }

    modal.classList.remove("hidden");
  }

  function closeFighterInspect(e) {
    if (e && e.target && e.target.closest && e.target.closest(".inspect-card") && !e.target.classList.contains("inspect-close-btn")) {
      return;
    }
    const modal = document.getElementById("screen-inspect");
    if (modal) modal.classList.add("hidden");
  }

  let _lastPlayerHpPct = null;
  let _lastEnemyHpPct = null;

  function updateHud() {
    if (typeof ensureBattleStateInitialized === "function") ensureBattleStateInitialized();
    const p = gameState.player;
    const e = gameState.enemy;

    const maxF = (typeof getMaxFloorsForDifficulty === "function") ? getMaxFloorsForDifficulty() : 13;
    const uiFloor = document.getElementById("ui-floor");
    if (uiFloor) {
      if (gameState.isCampaignMode) {
        const curAct = (typeof getActForFloor === "function") ? getActForFloor(gameState.floor) : 1;
        const curChapter = (typeof CAMPAIGN_CHAPTERS !== "undefined") ? (CAMPAIGN_CHAPTERS.find(c => c.number === curAct) || CAMPAIGN_CHAPTERS[0]) : null;
        const startF = curChapter?.startFloor || 1;
        const endF = curChapter?.endFloor || 3;
        const floorInAct = gameState.floor - startF + 1;
        const totalInAct = endF - startF + 1;
        const waveTxt = (gameState.floorEnemies && gameState.floorEnemies.length > 1) ? ` • ⚔️ OLEADA ${gameState.currentEnemyIndex + 1}/${gameState.floorEnemies.length}` : "";
        uiFloor.innerText = `${curChapter?.suit || "🗡️"} ACTO ${curAct} • P.${floorInAct}/${totalInAct}${waveTxt}`;
      } else {
        const waveTxt = (gameState.floorEnemies && gameState.floorEnemies.length > 1) ? ` • ⚔️ OLEADA ${gameState.currentEnemyIndex + 1}/${gameState.floorEnemies.length}` : "";
        uiFloor.innerText = `🏰 PISO ${gameState.floor} / ${maxF}${waveTxt}`;
      }
    }

    const uiGold = document.getElementById("ui-gold");
    if (uiGold) uiGold.innerHTML = `<img src="assets/svg/ui/icon_gold.svg" class="hud-icon" alt=""> ${gameState.gold}`;

    const uiKills = document.getElementById("ui-kills");
    if (uiKills) {
      const killsInCycle = gameState.killCount % 5;
      uiKills.innerHTML = `<img src="assets/svg/ui/icon_crypt.svg" class="hud-icon" alt=""> ${killsInCycle}/5`;
      uiKills.title = `💀 Bajas para Cofre de Cripta: ${killsInCycle}/5 (Cada 5 enemigos derrotados obtienes tributos abisales)`;
    }

    const pClassTitle = document.getElementById("player-class-title");
    if (pClassTitle) pClassTitle.innerText = p.name ? p.name.toUpperCase().replace(/^JACK\s+/i, "") : "CABALLERO";

    const pHpText = document.getElementById("player-hp-text");
    if (pHpText) pHpText.innerText = `${Math.max(0, p.hp)}/${p.maxHp}`;

    // Barra de vida e interpolación de barra de daño diferido (Ghost Bar, UX-01)
    const curPlayerHpPct = Math.max(0, Math.min(100, (p.hp / p.maxHp) * 100));
    const pHpBar = document.getElementById("player-hp-bar");
    const pGhostBar = document.getElementById("player-hp-ghost-bar");
    if (pHpBar) pHpBar.style.width = `${curPlayerHpPct}%`;
    if (pGhostBar) {
      if (_lastPlayerHpPct !== null && curPlayerHpPct < _lastPlayerHpPct) {
        pGhostBar.classList.add("active");
        setTimeout(() => { if (pGhostBar) pGhostBar.style.width = `${curPlayerHpPct}%`; }, 40);
        setTimeout(() => { if (pGhostBar) pGhostBar.classList.remove("active"); }, 650);
      } else {
        pGhostBar.style.width = `${curPlayerHpPct}%`;
      }
    }
    _lastPlayerHpPct = curPlayerHpPct;

    const lvlEl = document.getElementById("ui-player-lvl");
    if (lvlEl) lvlEl.innerText = p.level || 1;

    const neededExp = getExpRequiredForLevel(p.level || 1);
    p.nextLevelExp = neededExp;

    const expTextEl = document.getElementById("ui-player-exp-text");
    if (expTextEl) expTextEl.innerText = `${p.exp || 0}/${neededExp} EXP`;

    const expBarEl = document.getElementById("player-exp-bar");
    if (expBarEl) {
      const pct = Math.min(100, Math.round(((p.exp || 0) / neededExp) * 100));
      expBarEl.style.width = `${pct}%`;
    }

    const uiGem = document.getElementById("ui-gem");
    if (uiGem) {
      const sb = p.starterBlessing;
      if (sb) {
        const shortName = (sb.name || "Bendición").split(" ")[0].toUpperCase();
        uiGem.innerText = `${sb.icon || "🔮"} ${shortName}`;
        uiGem.className = `blessing-tier-text-${sb.tier || 1}`;
      } else if (p.gem) {
        uiGem.innerText = p.gem.toUpperCase();
      } else {
        uiGem.innerText = "NINGUNA";
      }
      if (uiGem.parentElement) {
        uiGem.parentElement.title = sb ? `${sb.name}: ${sb.desc}` : (p.gem ? (ITEM_INFO[p.gem] || p.gem) : "Sin bendición");
      }
    }

    const uiAcc = document.getElementById("ui-acc");
    if (uiAcc) {
      const accInfo = (p.accessory && typeof getAccessoryDisplay === "function") ? getAccessoryDisplay(p.accessory) : null;
      uiAcc.innerText = accInfo ? `${accInfo.icon} ${accInfo.short}` : "NINGUNO";
      if (uiAcc.parentElement) {
        uiAcc.parentElement.title = accInfo ? `${accInfo.name}: ${accInfo.desc}` : "Sin accesorio: se compra en el Bazar o en eventos";
      }
    }

    const uiArtifactsCount = document.getElementById("ui-artifacts-count");
    if (uiArtifactsCount) {
      const artLen = (p.artifacts && Array.isArray(p.artifacts)) ? p.artifacts.length : 0;
      const maxSlots = (typeof getMaxArtifactSlots === "function") ? getMaxArtifactSlots() : Math.min(5, p.level || 1);
      uiArtifactsCount.innerText = artLen + "/" + maxSlots;
      const pill = document.getElementById("ui-artifacts-pill");
      if (pill) {
        pill.title = "Ranuras de Artefactos: " + artLen + "/" + maxSlots + " (Máx 5 según tu Nivel de Jack)";
      }
    }

    const uiDupla = document.getElementById("ui-dupla");
    if (uiDupla) {
      uiDupla.innerText = p.duplaDef > 0 ? `SÍ (+ ${p.duplaDef} DEF)` : "NO";
      if (uiDupla.parentElement) {
        uiDupla.parentElement.title = p.duplaDef > 0 ? `DUPLA: tus 2 primeras cartas son iguales — + ${p.duplaDef} DEF durante esta mano` : "Dupla: si tus 2 primeras cartas son iguales, +2 DEF durante esa mano";
      }
    }

    const pMini = document.getElementById("player-stats-mini");
    if (pMini) {
      pMini.style.display = "none";
      pMini.classList.add("hidden");
    }

    const eMini = document.getElementById("enemy-stats-mini");
    if (eMini) {
      eMini.style.display = "none";
      eMini.classList.add("hidden");
    }

    if (typeof updatePlayerAccSlot === "function") {
      updatePlayerAccSlot();
    }

    // Control de Viñeta Roja y Estado de Salud del Héroe (Full, Mid, Low HP)
    const hpRatio = (p && p.maxHp > 0) ? (p.hp / p.maxHp) : 1;
    const vignetteEl = document.getElementById("low-hp-vignette");
    if (vignetteEl) {
      const isTitleHidden = document.getElementById("screen-title")?.classList.contains("hidden");
      if (hpRatio <= 0.30 && p && p.hp > 0 && isTitleHidden) {
        vignetteEl.classList.add("active");
      } else {
        vignetteEl.classList.remove("active");
      }
    }
    const pSprite = document.getElementById("player-sprite");
    if (pSprite) {
      pSprite.classList.remove("hp-full", "hp-mid", "hp-low");
      if (hpRatio <= 0.30) pSprite.classList.add("hp-low");
      else if (hpRatio <= 0.60) pSprite.classList.add("hp-mid");
      else pSprite.classList.add("hp-full");
    }

    if (e) {
      const eHpText = document.getElementById("enemy-hp-text");
      if (eHpText) eHpText.innerText = `${Math.max(0, e.hp)}/${e.maxHp}`;

      const curEnemyHpPct = Math.max(0, Math.min(100, (e.hp / e.maxHp) * 100));
      const eHpBar = document.getElementById("enemy-hp-bar");
      const eGhostBar = document.getElementById("enemy-hp-ghost-bar");
      if (eHpBar) eHpBar.style.width = `${curEnemyHpPct}%`;
      if (eGhostBar) {
        if (_lastEnemyHpPct !== null && curEnemyHpPct < _lastEnemyHpPct) {
          eGhostBar.classList.add("active");
          setTimeout(() => { if (eGhostBar) eGhostBar.style.width = `${curEnemyHpPct}%`; }, 40);
          setTimeout(() => { if (eGhostBar) eGhostBar.classList.remove("active"); }, 650);
        } else {
          eGhostBar.style.width = `${curEnemyHpPct}%`;
        }
      }
      _lastEnemyHpPct = curEnemyHpPct;
    }

    const pShield = gameState.status.playerShield || 0;
    const pShieldBar = document.getElementById("player-shield-bar");
    const pShieldText = document.getElementById("player-shield-text");
    const pShieldWrapper = document.getElementById("player-shield-wrapper");
    if (pShieldBar && pShieldText) {
      const effDef = (p.def || 0) + (p.turnShieldBonus || 0) + (p.duplaDef || 0) + (p._synergyBonusDef || 0);
      const pMaxShield = Math.max(pShield, 10 + effDef);
      const pct = pMaxShield > 0 ? Math.min(100, Math.max(0, (pShield / pMaxShield) * 100)) : 0;
      pShieldBar.style.width = `${pct}%`;
      pShieldText.innerText = `${pShield}/${pMaxShield}`;
      if (pShieldWrapper) {
        if (pShield > 0) pShieldWrapper.classList.add("has-shield");
        else pShieldWrapper.classList.remove("has-shield");
      }
    }

    const eShield = gameState.status.enemyShield || 0;
    const eShieldBar = document.getElementById("enemy-shield-bar");
    const eShieldText = document.getElementById("enemy-shield-text");
    const eShieldWrapper = document.getElementById("enemy-shield-wrapper");
    if (eShieldBar && eShieldText) {
      const eMaxShield = Math.max(eShield, (e && e.def ? e.def + 10 : 10));
      const pct = eMaxShield > 0 ? Math.min(100, Math.max(0, (eShield / eMaxShield) * 100)) : 0;
      eShieldBar.style.width = `${pct}%`;
      eShieldText.innerText = `${eShield}/${eMaxShield}`;
      if (eShieldWrapper) {
        if (eShield > 0) eShieldWrapper.classList.add("has-shield");
        else eShieldWrapper.classList.remove("has-shield");
      }
    }

    const btnPotion = document.getElementById("btn-potion");
    if (btnPotion) {
      btnPotion.innerText = `🧪 POCIÓN (${p.potions})`;
    }

    // Actualizar Estante y Contador de Sinergias Activas en Combate
    const synShelf = document.getElementById("active-synergies-shelf");
    const synCountEl = document.getElementById("ui-synergies-count");
    const activeSyns = [];
    if (p && p.activeHandSynergies) {
      if (p.activeHandSynergies["fire"]) activeSyns.push({ icon: "🔥", name: "Explosión Ígnea", desc: "10 Daño directo + Quemadura" });
      if (p.activeHandSynergies["blood"]) activeSyns.push({ icon: "🩸", name: "Pacto Carmesí", desc: "+HP y purga veneno" });
      if (p.activeHandSynergies["shield"]) activeSyns.push({ icon: "🛡️", name: "Baluarte Acero", desc: "+10 Escudo azul" });
      if (p.activeHandSynergies["blade"]) activeSyns.push({ icon: "⚔️", name: "Frenesí de Filo", desc: "+8 Daño de impacto" });
      if (p.activeHandSynergies["toxic"]) activeSyns.push({ icon: "☠️", name: "Peste Tóxica", desc: "Veneno masivo al rival" });
      if (p.activeHandSynergies["arcane"]) activeSyns.push({ icon: "🔮", name: "Convergencia", desc: "+1 Reroll gratis" });
    }
    if (synCountEl) synCountEl.innerText = String(activeSyns.length);
    if (synShelf) {
      if (activeSyns.length > 0) {
        synShelf.classList.remove("hidden");
        synShelf.innerHTML = activeSyns.map(s => `
          <div class="synergy-chip" onclick="explainEquipmentPill('synergies')" title="${s.desc}">
            <span>${s.icon}</span> <b>${s.name}</b>
          </div>
        `).join("");
      } else {
        synShelf.classList.add("hidden");
        synShelf.innerHTML = "";
      }
    }

    // SPRINT 2: Contador de manos traslúcido en el centro superior de la mesa
    updateHUDHandNumber();

    if (typeof updateTacticalDamagePredictor === "function") updateTacticalDamagePredictor();
  }

  /* ============================================================
     SET BUTTONS DISABLED
     ============================================================ */
  function setButtonsDisabled(disabled) {
    const btns = document.querySelectorAll("#action-grid button");
    btns.forEach(btn => { btn.disabled = disabled; });
  }

  /* ============================================================
     LOG
     ============================================================ */
  function addLog(msg, type) {
    type = type || "info";
    const lc = document.getElementById("log-container");
    if (!lc) return;
    const entry = (document.createElement) ? document.createElement("div") : {};
    entry.className = "log-entry " + type;
    entry.innerText = msg;
    if (lc.appendChild) lc.appendChild(entry);
    if (typeof lc.scrollHeight === "number") lc.scrollTop = lc.scrollHeight;

    const logModal = document.getElementById("modal-combat-log");
    const unreadDot = document.getElementById("combat-log-unread-dot");
    if (logModal && logModal.classList.contains("hidden") && unreadDot) {
      unreadDot.classList.remove("hidden");
    }

    if (lc.children && lc.children.length) {
      while (lc.children.length > 30) {
        if (lc.removeChild && lc.firstChild) {
          lc.removeChild(lc.firstChild);
        } else {
          break;
        }
      }
    }
  }

  /* ============================================================
     v1.9.0 — MODALES FLOTANTES DE COMBATE (MOCHILA & LOG DE TURNO)
     ============================================================ */
  function openCombatGearModal() {
    const modal = document.getElementById("modal-combat-gear");
    if (!modal) return;
    updateCombatGearModalUI();
    const titleEl = document.getElementById("gear-detail-title");
    const descEl = document.getElementById("gear-detail-desc");
    if (titleEl && descEl) {
      const p = (typeof gameState !== "undefined" && gameState.player) ? gameState.player : null;
      const cleanArts = (p && typeof sanitizePlayerArtifacts === "function") ? sanitizePlayerArtifacts(p) : (p && p.artifacts ? p.artifacts : []);
      if (cleanArts && cleanArts.length > 0) {
        inspectGearSlot("artifact", cleanArts[0]);
      } else {
        inspectGearSlot("blessing", null);
      }
    }
    modal.classList.remove("hidden");
    modal.style.display = "flex";
    try { playButtonClickSound(); } catch (_) {}
  }
  window.openCombatGearModal = openCombatGearModal;

  function closeCombatGearModal() {
    const modal = document.getElementById("modal-combat-gear");
    if (modal) {
      modal.classList.add("hidden");
      modal.style.display = "none";
    }
  }
  window.closeCombatGearModal = closeCombatGearModal;

  function openCombatLogModal() {
    const modal = document.getElementById("modal-combat-log");
    if (!modal) return;
    modal.classList.remove("hidden");
    modal.style.display = "flex";
    const unreadDot = document.getElementById("combat-log-unread-dot");
    if (unreadDot) unreadDot.classList.add("hidden");
    const logCont = document.getElementById("log-container");
    if (logCont) logCont.scrollTop = logCont.scrollHeight;
    try { playButtonClickSound(); } catch (_) {}
  }
  window.openCombatLogModal = openCombatLogModal;

  function closeCombatLogModal() {
    const modal = document.getElementById("modal-combat-log");
    if (modal) {
      modal.classList.add("hidden");
      modal.style.display = "none";
    }
  }
  window.closeCombatLogModal = closeCombatLogModal;

  function updateCombatGearModalUI() {
    const p = (typeof gameState !== "undefined" && gameState.player) ? gameState.player : null;
    if (!p) return;
    const cleanArts = (typeof sanitizePlayerArtifacts === "function") ? sanitizePlayerArtifacts(p) : (p.artifacts || []);
    const maxSlots = 5;

    const countEl = document.getElementById("gear-modal-art-count");
    if (countEl) countEl.innerText = `${cleanArts.length}/${maxSlots}`;

    const badgeBtn = document.getElementById("combat-gear-badge");
    if (badgeBtn) badgeBtn.innerText = `${cleanArts.length}/${maxSlots}`;

    const gridEl = document.getElementById("gear-modal-artifacts-grid");
    if (gridEl) {
      let html = "";
      for (let i = 0; i < maxSlots; i++) {
        if (i < cleanArts.length) {
          const artId = cleanArts[i];
          let info = null;
          if (typeof SHOP_ARTIFACTS !== "undefined") {
            info = SHOP_ARTIFACTS.find(a => a.id === artId);
          }
          if (!info && typeof DEMONIC_RELICS_BY_ACT !== "undefined") {
            for (const list of Object.values(DEMONIC_RELICS_BY_ACT)) {
              const found = list.find(d => d.id === artId);
              if (found) { info = found; break; }
            }
          }
          if (!info && typeof ALL_RELICS !== "undefined") {
            info = ALL_RELICS.find(r => r.id === artId);
          }
          const name = info ? info.name : String(artId);
          const icon = info ? (info.icon || "🎴") : "🎴";
          html += `
            <div class="gear-art-slot filled" onclick="inspectGearSlot('artifact', '${artId}')" title="${name}">
              <span class="gear-slot-icon">${icon}</span>
              <span class="gear-art-slot-num">${i + 1}</span>
            </div>
          `;
        } else {
          html += `
            <div class="gear-art-slot empty" onclick="inspectGearSlot('artifact', null)" title="Ranura Libre">
              <span class="gear-slot-icon">+</span>
              <span class="gear-art-slot-num">${i + 1}</span>
            </div>
          `;
        }
      }
      gridEl.innerHTML = html;
    }

    const isEn = (typeof getGameLanguage === "function" && getGameLanguage() === "en");
    const activeBlessing = p ? (p.starterBlessing || p.blessing || p.activeBlessing || p.gem) : null;
    const gemBtn = document.getElementById("ui-gem-pill");
    const gemTag = document.getElementById("ui-gem-tag");
    const gemIcon = document.getElementById("ui-gem-icon");
    if (gemBtn) {
      if (activeBlessing) {
        gemBtn.classList.add("active");
        let bName = "BENDICIÓN";
        let bIcon = "💎";
        if (typeof activeBlessing === "object") {
          bName = activeBlessing.name || "BENDICIÓN";
          bIcon = activeBlessing.icon || "💎";
        } else if (typeof STARTER_BLESSINGS !== "undefined") {
          const bl = STARTER_BLESSINGS.find(b => b.id === activeBlessing);
          if (bl) { bName = bl.name; bIcon = bl.icon || "💎"; }
        } else if (p.gem) {
          bName = (typeof getItemSpanishName === "function" ? getItemSpanishName(p.gem) : p.gem);
          bIcon = "💎";
        }
        if (gemTag) gemTag.innerText = bName.length > 11 ? bName.slice(0, 10) + "…" : bName;
        if (gemIcon) gemIcon.innerText = bIcon;
      } else {
        gemBtn.classList.remove("active");
        if (gemTag) gemTag.innerText = isEn ? "NO BLESSING" : "SIN BENDICIÓN";
        if (gemIcon) gemIcon.innerText = "💎";
      }
    }

    const accEl = document.getElementById("ui-acc");
    if (accEl) {
      accEl.innerText = p.accessory ? (typeof getItemSpanishName === "function" ? getItemSpanishName(p.accessory) : p.accessory.toUpperCase()) : (isEn ? "NONE" : "NINGUNO");
    }
    const accBtn = document.getElementById("ui-acc-pill");
    if (accBtn) {
      if (p.accessory) accBtn.classList.add("active");
      else accBtn.classList.remove("active");
    }

    const duplaEl = document.getElementById("ui-dupla");
    if (duplaEl) {
      duplaEl.innerText = (p.duplaDef > 0) ? (isEn ? `YES (+${p.duplaDef} DEF)` : `SÍ (+${p.duplaDef} DEF)`) : (isEn ? "NO" : "NO");
    }
    const duplaBtn = document.getElementById("ui-dupla-pill");
    if (duplaBtn) {
      if (p.duplaDef > 0) duplaBtn.classList.add("active");
      else duplaBtn.classList.remove("active");
    }

    const synEl = document.getElementById("ui-synergies-count");
    if (synEl && p.activeHandSynergies) {
      const totalSyns = Object.keys(p.activeHandSynergies).filter(k => p.activeHandSynergies[k]).length;
      synEl.innerText = String(totalSyns);
    }

    const perksListEl = document.getElementById("gear-modal-perks-list");
    if (perksListEl) {
      const activePerks = [];
      if (typeof getPlayerActiveTacticalPerks === "function") {
        activePerks.push(...getPlayerActiveTacticalPerks());
      }
      if (activePerks.length > 0) {
        perksListEl.innerHTML = activePerks.map(perk => `
          <div class="gear-perk-item">
            <span class="gear-perk-icon">${perk.icon || '💡'}</span>
            <div class="gear-perk-info">
              <div class="gear-perk-name">${perk.name}</div>
              <div class="gear-perk-desc">${perk.desc}</div>
            </div>
          </div>
        `).join("");
      } else {
        const emptyText = isEn
          ? "No active tactical perks in this hand. Complete card conditions to trigger situational synergies."
          : "Sin perks tácticos activos en esta mano. Cumple condiciones de naipes para activar sinergias situacionales.";
        perksListEl.innerHTML = `<div class="gear-empty-notice">${emptyText}</div>`;
      }
    }
  }
  window.updateCombatGearModalUI = updateCombatGearModalUI;

  function inspectGearSlot(type, id) {
    try { playButtonClickSound(); } catch (_) {}
    const p = (typeof gameState !== "undefined" && gameState.player) ? gameState.player : null;
    const isEn = (typeof getGameLanguage === "function" && getGameLanguage() === "en");
    const titleEl = document.getElementById("gear-detail-title");
    const descEl = document.getElementById("gear-detail-desc");
    if (!titleEl || !descEl) return;

    if (type === "artifact") {
      let info = null;
      if (id && typeof SHOP_ARTIFACTS !== "undefined") info = SHOP_ARTIFACTS.find(a => a.id === id);
      if (!info && id && typeof DEMONIC_RELICS_BY_ACT !== "undefined") {
        for (const list of Object.values(DEMONIC_RELICS_BY_ACT)) {
          const found = list.find(d => d.id === id);
          if (found) { info = found; break; }
        }
      }
      if (!info && id && typeof ALL_RELICS !== "undefined") info = ALL_RELICS.find(r => r.id === id);
      if (info) {
        titleEl.innerHTML = `${info.icon || '🎴'} ${(info.name || id).toUpperCase()}`;
        descEl.innerText = info.desc || "Artefacto pasivo que otorga ventajas estratégicas permanentes durante el ascenso.";
      } else {
        titleEl.innerHTML = "🎴 RANURA DE ARTEFACTO LIBRE";
        descEl.innerText = "Esta ranura está disponible. Puedes adquirir hasta 5 artefactos pasivos en la Tienda o en eventos de la Torre.";
      }
    } else if (type === "blessing") {
      const activeBlessingId = p ? (p.starterBlessing || p.blessing || p.activeBlessing) : null;
      let blessingInfo = null;
      if (activeBlessingId && typeof STARTER_BLESSINGS !== "undefined") {
        blessingInfo = STARTER_BLESSINGS.find(b => b.id === activeBlessingId || b.id === (typeof activeBlessingId === "object" ? activeBlessingId.id : activeBlessingId));
      }
      if (!blessingInfo && typeof activeBlessingId === "object" && activeBlessingId) {
        blessingInfo = activeBlessingId;
      }
      if (blessingInfo) {
        titleEl.innerHTML = `${blessingInfo.icon || '💎'} ${(blessingInfo.name || 'BENDICIÓN ACTIVA').toUpperCase()}`;
        descEl.innerText = blessingInfo.desc || "Bendición divina inicial que acompaña a tu héroe en la Torre.";
        return;
      }
      if (p && p.gem) {
        titleEl.innerHTML = `💎 MEDALLÓN: ${(typeof getItemSpanishName === "function" ? getItemSpanishName(p.gem) : p.gem).toUpperCase()}`;
        descEl.innerText = "Gema engarzada en tu medallón de combate. Amplifica bonificaciones según el elemento de tus cartas.";
      } else {
        titleEl.innerHTML = isEn ? "💎 NO ACTIVE BLESSING" : "💎 SIN BENDICIÓN ACTIVA";
        descEl.innerText = isEn
          ? "No destiny blessing or medallion gem currently equipped. Discover shrines or choose starting blessings."
          : "No tienes ninguna bendición del destino equipada en tu medallón en este momento.";
      }
    } else if (type === "accessory") {
      const acc = (p && p.accessory && typeof AMULET_INFO !== "undefined" && AMULET_INFO[p.accessory]) ? AMULET_INFO[p.accessory] : null;
      if (acc) {
        titleEl.innerHTML = `💍 ${(acc.name || 'ACCESORIO').toUpperCase()}`;
        descEl.innerText = acc.desc || "Accesorio protector equipado.";
      } else {
        titleEl.innerHTML = "💍 RANURA DE ACCESORIO";
        descEl.innerText = "Sin accesorio equipado. Visita la Tienda (Pestaña 2) para adquirir anillos y amuletos defensivos.";
      }
    } else if (type === "dupla") {
      const hasDupla = (p && p.duplaDef > 0);
      titleEl.innerHTML = hasDupla ? `⚡ DUPLA ACTIVA (+${p.duplaDef} DEF)` : "⚡ DUPLA DEFENSIVA";
      descEl.innerText = hasDupla
        ? "¡Tus cartas iniciales tienen el mismo valor numérico! La barrera suma armadura directa en esta mano."
        : "Si tus dos primeras cartas coinciden en valor (ej. dos Reyes o dos 7), activas un bono defensivo automático.";
    } else if (type === "synergies") {
      const synList = [];
      if (p && p.activeHandSynergies) {
        if (p.activeHandSynergies["fire"]) synList.push("🔥 Fuego (+10 Daño)");
        if (p.activeHandSynergies["blood"]) synList.push("🩸 Sangre (Cura vida)");
        if (p.activeHandSynergies["shield"]) synList.push("🛡️ Acero (+10 Escudo)");
        if (p.activeHandSynergies["blade"]) synList.push("⚔️ Hojas (+8 Daño)");
        if (p.activeHandSynergies["toxic"]) synList.push("☠️ Veneno (Toxina)");
        if (p.activeHandSynergies["arcane"]) synList.push("🔮 Arcano (+1 Reroll)");
      }
      titleEl.innerHTML = `🔮 SINERGIAS ELEMENTALES (${synList.length})`;
      descEl.innerText = synList.length > 0
        ? `Activas en esta mano: ${synList.join(" • ")}.`
        : "Reúne dos o más cartas del mismo elemento para activar efectos mágicos situacionales.";
    }
  }
  window.inspectGearSlot = inspectGearSlot;

