  window.ACHIEVEMENTS_CATALOG = ACHIEVEMENTS_CATALOG;

  function getUnlockedAchievements() {
    try {
      const raw = localStorage.getItem("bj_achievements_v1");
      return raw ? JSON.parse(raw) : {};
    } catch (_) { return {}; }
  }
  window.getUnlockedAchievements = getUnlockedAchievements;

  function unlockAchievement(achId) {
    const ach = ACHIEVEMENTS_CATALOG.find(a => a.id === achId);
    if (!ach) return;
    const unlocked = getUnlockedAchievements();
    if (unlocked[achId]) return;

    unlocked[achId] = Date.now();
    try {
      localStorage.setItem("bj_achievements_v1", JSON.stringify(unlocked));
    } catch (_) {}

    try { playWinFanfareSound(); } catch (_) {}
    if (typeof showGameToast === "function") {
      showGameToast(`🏆 ¡LOGRO DESBLOQUEADO!\n${ach.name} — ${ach.desc}`, "epic");
    }
  }
  window.unlockAchievement = unlockAchievement;

  let currentAchievementsFilter = "all";

  function openAchievementsModal(family = "all") {
    currentAchievementsFilter = family;
    renderAchievementsList();
    const modal = document.getElementById("screen-achievements-modal");
    if (modal) modal.classList.remove("hidden");
    try { playButtonClickSound(); } catch (_) {}
  }
  window.openAchievementsModal = openAchievementsModal;

  function closeAchievementsModal() {
    const modal = document.getElementById("screen-achievements-modal");
    if (modal) modal.classList.add("hidden");
  }
  window.closeAchievementsModal = closeAchievementsModal;

  function filterAchievementsFamily(family) {
    currentAchievementsFilter = family;
    const btns = document.querySelectorAll(".ach-filter-btn");
    btns.forEach(btn => {
      if (btn.getAttribute("data-family") === family) btn.classList.add("active");
      else btn.classList.remove("active");
    });
    renderAchievementsList();
    try { playButtonClickSound(); } catch (_) {}
  }
  window.filterAchievementsFamily = filterAchievementsFamily;

  function renderAchievementsList() {
    const listEl = document.getElementById("achievements-list");
    if (!listEl) return;

    const unlocked = getUnlockedAchievements();
    const totalCount = ACHIEVEMENTS_CATALOG.length;
    const unlockedCount = Object.keys(unlocked).length;
    const percent = Math.round((unlockedCount / Math.max(1, totalCount)) * 100);

    const fillEl = document.getElementById("ach-progress-fill");
    const pctEl = document.getElementById("ach-progress-percent");
    const cntEl = document.getElementById("ach-progress-count");
    if (fillEl) fillEl.style.width = `${percent}%`;
    if (pctEl) pctEl.innerText = `${percent}%`;
    if (cntEl) cntEl.innerText = `${unlockedCount} / ${totalCount} Desafíos Completados`;

    const catTitles = {
      all: `🏆 TODOS LOS DESAFÍOS (${totalCount})`,
      tower: "🏰 DESAFÍOS DE LA TORRE (PISOS Y ASCENSIÓN)",
      combat: "⚔️ DESAFÍOS DE COMBATE (MAESTRÍA Y CRÍTICOS)",
      economy: "🪙 DESAFÍOS DE ECONOMÍA (BOTÍN Y FORTUNA)",
      collection: "🃏 DESAFÍOS DE COLECCIÓN (MAZOS Y CÓDICE)",
      arena: "🥊 DESAFÍOS DE LA ARENA (DUELOS A K.O.)"
    };
    const catTitleEl = document.getElementById("ach-active-category-title");
    if (catTitleEl) {
      catTitleEl.innerText = catTitles[currentAchievementsFilter] || "🏆 DESAFÍOS";
    }

    const filtered = currentAchievementsFilter === "all"
      ? ACHIEVEMENTS_CATALOG
      : ACHIEVEMENTS_CATALOG.filter(a => a.family === currentAchievementsFilter);

    listEl.innerHTML = filtered.map(ach => {
      const isDone = !!unlocked[ach.id];
      return `
        <div class="achievement-row ${isDone ? 'unlocked' : ''}">
          <div class="ach-icon-box">${ach.icon}</div>
          <div class="ach-info-box">
            <div class="ach-name">${ach.name} ${isDone ? '<span>✓</span>' : ''}</div>
            <div class="ach-desc">${ach.desc}</div>
          </div>
          <div class="ach-status-badge ${isDone ? 'done' : 'locked'}">
            ${isDone ? 'COMPLETADO' : 'BLOQUEADO'}
          </div>
        </div>
      `;
    }).join("");
  }
  window.renderAchievementsList = renderAchievementsList;

  /* ============================================================
     VISOR DE BARAJA DEL JUGADOR (52 CARTAS ACTIVAS)
     ============================================================ */
  let currentDeckViewerFilter = "all";

  function openDeckViewerModal() {
    const modal = document.getElementById("screen-deck-viewer");
    if (!modal) return;
    currentDeckViewerFilter = "all";
    const filterBtns = modal.querySelectorAll(".deck-filter-btn");
    filterBtns.forEach(btn => {
      if (btn.getAttribute("data-filter") === "all" || btn.innerText.includes("TODAS")) btn.classList.add("active");
      else btn.classList.remove("active");
    });
    renderDeckViewerContent();
    modal.classList.remove("hidden");
    try { playButtonClickSound(); } catch (_) {}
  }
  window.openDeckViewerModal = openDeckViewerModal;

  function closeDeckViewerModal(e) {
    if (e && e.target && e.target.id !== "screen-deck-viewer" && !e.target.classList.contains("inspect-close-btn") && !e.target.classList.contains("deck-close-action")) {
      return;
    }
    const modal = document.getElementById("screen-deck-viewer");
    if (modal) modal.classList.add("hidden");
    try { playButtonClickSound(); } catch (_) {}
  }
  window.closeDeckViewerModal = closeDeckViewerModal;

  function filterDeckViewer(filterKey, btnEl) {
    currentDeckViewerFilter = filterKey;
    const modal = document.getElementById("screen-deck-viewer");
    if (modal) {
      modal.querySelectorAll(".deck-filter-btn").forEach(b => b.classList.remove("active"));
    }
    if (btnEl) btnEl.classList.add("active");
    renderDeckViewerContent();
    try { playButtonClickSound(); } catch (_) {}
  }
  window.filterDeckViewer = filterDeckViewer;

  function renderDeckViewerContent() {
    const grid = document.getElementById("deck-viewer-grid");
    const summary = document.getElementById("deck-viewer-summary");
    if (!grid) return;

    let deck = (gameState && Array.isArray(gameState.deck) && gameState.deck.length > 0)
      ? gameState.deck
      : ((typeof buildStandardDeck === "function") ? buildStandardDeck() : []);

    const isCardArcane = (c) => !!c.isWonCard || !!c.fusion || !!c.modifier || !!c.operator || (Array.isArray(c.dynamicValues) && c.dynamicValues.length > 0) || !!c.specialId;
    const arcaneCount = deck.filter(isCardArcane).length;
    if (summary) {
      summary.innerHTML = `Baraja Activa: <b>${deck.length} Cartas</b> • <b>${arcaneCount} Naipes Arcanos de Jefe</b>`;
    }

    let filtered = deck;
    if (currentDeckViewerFilter === "spades") {
      filtered = deck.filter(c => c.suit === "♠" || c.suit === "spades");
    } else if (currentDeckViewerFilter === "hearts") {
      filtered = deck.filter(c => c.suit === "♥" || c.suit === "hearts");
    } else if (currentDeckViewerFilter === "diamonds") {
      filtered = deck.filter(c => c.suit === "♦" || c.suit === "diamonds");
    } else if (currentDeckViewerFilter === "clubs") {
      filtered = deck.filter(c => c.suit === "♣" || c.suit === "clubs");
    } else if (currentDeckViewerFilter === "arcane") {
      filtered = deck.filter(isCardArcane);
    }

    if (filtered.length === 0) {
      grid.innerHTML = `<div class="deck-viewer-empty">No hay cartas en este filtro.</div>`;
      return;
    }

    grid.innerHTML = filtered.map(card => {
      const arcane = isCardArcane(card);
      const isRed = (card.suit === "♥" || card.suit === "♦" || card.suit === "hearts" || card.suit === "diamonds");
      const colorClass = isRed ? "card-red" : "card-black";
      const arcaneClass = arcane ? "card-transmuted-arcane card-holographic" : "";
      const badge = arcane ? '<span class="card-loot-badge arcane-sigil" title="Naipe Arcano">✦</span>' : '';

      const cosmetic = card.cosmetic || (typeof getCosmeticForCard === "function" ? getCosmeticForCard(card) : null);
      const cosmeticClass = cosmetic ? `card-cosmetic-fullart cosmetic-tier-${cosmetic.tier || 'common'}` : '';

      let cosmeticBgHtml = "";
      if (cosmetic) {
        const bgImg = cosmetic.img || getEnemySvgFallback(cosmetic.id || cosmetic.enemyId);
        cosmeticBgHtml = `
          <div class="card-cosmetic-bg" style="background-image: url('${bgImg}');"></div>
          <div class="card-cosmetic-vignette"></div>
          <span class="card-cosmetic-crown" title="Carta Cosmética: ${cosmetic.enemyName}">👑</span>
        `;
      }

      const bonusDesc = card.fusion ? `Fusión: ${card.fusion.name || 'Arcana'}` :
                        (card.modifier ? `Mod: ${card.modifier.name || card.modifier.type}` :
                        (card.operator ? `Op: ${card.operator.label || card.operator.type}` :
                        (cosmetic ? `👑 ${cosmetic.enemyName}` :
                        (arcane ? 'Naipe de Jefe' : 'Naipe Común'))));

      return `
        <div class="deck-card-item ${arcaneClass} ${colorClass} ${cosmeticClass}">
          ${cosmeticBgHtml}
          <div class="deck-card-top">
            <span class="deck-card-rank">${card.rank || card.value}</span>
            <span class="deck-card-suit">${card.suit}</span>
            ${badge}
          </div>
          <div class="deck-card-center">${card.suit}</div>
          <div class="deck-card-desc">${bonusDesc}</div>
        </div>
      `;
    }).join("");
  }
  window.renderDeckViewerContent = renderDeckViewerContent;
